part of '../main.dart';

class IntelligentInvestorBookPage extends StatelessWidget {
  const IntelligentInvestorBookPage({super.key});

  static const _chapters = <_BookChapter>[
    _BookChapter(
      title: 'Ch1. 투자와 투기의 차이',
      body: '''시장에 들어온 모든 사람은 투자자일까?
닷컴버블은 인터넷이라는 단어만 붙으면 주가가 오르던 시기였다. 어떤 기업은 매출도 없었고 이익도 없었다. 심지어 사업 모델조차 불분명했다. 그러나 투자자들은 열광했다. 주가는 매일 올랐다. 언론은 새로운 부자들의 이야기를 쏟아냈다. 대학생들은 강의실보다 주식 게시판을 더 자주 들여다봤고, 직장인들은 점심시간마다 종목 토론을 했다.

당시 많은 사람들은 자신을 투자자라고 생각했다. 하지만 내가 그 모습을 보았다면 아마 이렇게 말했을 것이다. "그들은 투자자가 아니다." 그들은 투기꾼이었다.

2000년 버블이 무너진 뒤 수많은 기업들이 사라졌다. 하루아침에 수십 퍼센트의 손실이 발생했고, 평생 모은 자산을 잃은 사람들도 적지 않았다. 흥미로운 점은 돈을 잃은 사람들 대부분이 자신이 무엇을 샀는지 제대로 설명하지 못했다는 사실이다. 그들은 기업을 산 것이 아니라 가격 상승을 샀다. 이것이 바로 투자와 투기의 차이다.

투자와 투기는 완전히 다른 게임이다

대부분의 사람들은 투자와 투기를 비슷한 것으로 생각한다. 주식을 사면 투자이고, 코인을 사면 투기라고 생각하는 사람도 있다. 하지만 나는 전혀 다르게 생각한다. 나는 이 글에서 투자란 다음 세 가지 조건을 만족해야 한다고 말한다.

첫째, 충분한 분석이 있어야 한다. 둘째, 원금 보호가 고려되어야 한다. 셋째, 만족스러운 수익을 기대할 수 있어야 한다. 이 조건을 충족하지 못하면 모두 투기라고 나는 정의한다.

중요한 것은 무엇을 사느냐가 아니다. 어떤 생각으로 사느냐가 중요하다. 애플 주식을 사더라도 이유가 "내일 오를 것 같아서"라면 투기다. 반대로 ETF를 사더라도 기업의 성장성과 장기적인 경제 발전을 분석한 결과라면 투자에 가깝다. 상품이 투자와 투기를 나누는 것이 아니다. 사고방식이 나눈다.

가격은 매일 변하지만 가치는 천천히 변한다

주식 시장에 처음 들어온 사람들은 대부분 가격에 집중한다. 오늘 몇 퍼센트 올랐는지, 이번 주에 얼마나 수익이 났는지, 다른 사람들은 어떤 종목을 사고 있는지. 하지만 투자자는 가격보다 가치를 본다.

예를 들어보자. 당신이 서울 강남에 건물 한 채를 가지고 있다고 가정해 보자. 어느 날 누군가 와서 50억 원에 사겠다고 말한다. 다음 날에는 40억 원에 사겠다고 말한다. 그리고 일주일 뒤에는 다시 55억 원에 사겠다고 말한다. 건물 자체는 아무것도 변하지 않았다. 임대료도 그대로다. 입지도 그대로다. 건물 가치도 크게 변하지 않았다. 변한 것은 제안 가격뿐이다.

주식도 마찬가지다. 시장 가격은 매일 움직인다. 그러나 기업의 가치는 그렇게 빨리 변하지 않는다. 투자자는 가치를 본다. 투기꾼은 가격만 본다.

인간은 원래 투기를 좋아한다

투자가 어려운 이유는 인간의 본능 때문이다. 사람들은 천천히 부자가 되는 것을 싫어한다. 연 10% 수익률을 20년 동안 유지하는 이야기는 지루하다. 하지만 한 달 만에 300% 상승한 종목 이야기는 흥미롭다. 그래서 사람들은 자연스럽게 투기로 끌린다.

우리의 뇌는 원래 즉각적인 보상을 선호하도록 설계되어 있다. 오늘 1%를 버는 것보다 내일 100%를 벌 가능성에 더 흥분한다. 문제는 시장이 그런 심리를 끊임없이 이용한다는 점이다.

상승장에서는 누구나 천재처럼 보인다. 어떤 종목을 사도 오른다. 주변 사람들은 돈을 번다. SNS는 수익 인증으로 가득하다. 그 순간 투자자는 자신도 모르게 생각한다. "나만 뒤처지는 것 아닐까?" 바로 그 순간부터 분석은 사라지고 감정이 투자 결정을 지배하기 시작한다.

워런 버핏은 왜 부자가 되었을까

많은 사람들은 워런 버핏이 엄청난 투자 기술을 가지고 있다고 생각한다. 물론 사실이다. 하지만 그의 가장 강력한 무기는 종목 선정 능력이 아니다. 시간이다.

버핏은 젊은 시절부터 좋은 기업을 찾아 오랫동안 보유했다. 그는 하루 뒤의 주가를 예측하려 하지 않았다. 다음 달의 금리를 맞추려 하지 않았다. 다음 분기의 실적을 예측하려 하지도 않았다. 그는 단순한 질문에 집중했다. "이 기업이 10년 뒤에도 강할까?" "20년 뒤에도 살아남을까?" 이 질문이 그의 인생을 바꿨다. 실제로 버핏 재산의 대부분은 60세 이후에 만들어졌다. 복리가 작동할 시간을 충분히 주었기 때문이다. 투기꾼은 시간을 적으로 생각한다. 투자자는 시간을 친구로 만든다.

현대 투자자에게 ETF가 중요한 이유

내가 처음 투자를 배우던 시절에는 대부분 펀드였었다. 하지만 오늘날 개인 투자자는 훨씬 유리한 환경에 있다. QQQ, SPY, VOO, 그리고 QLD 같은 ETF가 존재한다. 이 상품들은 수십 개, 수백 개 기업에 자동으로 분산 투자할 수 있게 해준다.

하지만 한 가지는 변하지 않았다. ETF도 투자로 사용할 수 있고 투기로 사용할 수도 있다는 점이다. 매일 가격만 바라본다면 ETF 역시 투기 도구가 된다. 반대로 장기적인 경제 성장에 참여한다는 관점으로 접근한다면 훌륭한 투자 수단이 된다.

QLD 투자자는 무엇에 투자하는가

많은 사람들은 QLD를 단순히 레버리지 ETF라고 생각한다. 하지만 그것은 절반만 맞는 이야기다. QLD는 나스닥100 지수의 약 2배 수익률을 추구한다. 즉, QLD를 보유한다는 것은 단순히 ETF를 보유하는 것이 아니라 미국 기술 혁신에 참여하는 것이다. 애플, 마이크로소프트, 엔비디아, 아마존, 메타, 브로드컴 — 이러한 기업들이 앞으로도 성장할 것이라고 믿는다면 QLD는 투자 대상이 될 수 있다. 하지만 단순히 "다음 달에 오를 것 같다"는 이유로 접근한다면 그것은 투기에 불과하다. 같은 상품, 다른 생각. 결과는 완전히 달라진다.

투자자의 가장 큰 적

초보 투자자들은 시장을 두려워한다. 폭락을 두려워한다. 경제 위기를 두려워한다. 하지만 시간이 지나면 진짜 적이 누구인지 알게 된다. 투자자의 가장 큰 적은 시장이 아니다. 자기 자신이다. 공포, 탐욕, 조급함, 후회, 질투 — 이 감정들이 수많은 투자자를 시장 밖으로 밀어낸다. 시장은 결국 회복하는 경우가 많다. 그러나 공포에 무너진 투자자는 회복하지 못한다. 그래서 투자의 본질은 종목 선택이 아니다. 심리 관리다.

Chapter 1 핵심 정리
투자와 투기는 완전히 다르다.
투자자는 가치를 사고 투기꾼은 가격을 산다.
가격은 매일 변하지만 가치는 천천히 변한다.
인간의 본성은 투기를 좋아한다.
워런 버핏의 가장 큰 무기는 예측이 아니라 시간이었다.
ETF도 투자 수단이 될 수 있고 투기 수단이 될 수도 있다.
QLD는 미국 기술 혁신에 대한 장기 투자 관점으로 접근해야 한다.
투자자의 가장 큰 적은 시장이 아니라 자신의 감정이다.

기억해야 할 문장

"투자는 미래를 맞추는 게임이 아니다. 좋은 자산을 적절한 가격에 사고, 충분한 시간을 주는 과정이다."''',
    ),
    _BookChapter(
      title: 'Ch2. 왜 대부분의 투자자는 실패하는가',
      body: '''시장은 어렵지 않다. 하지만 인간의 감정은 어렵다.
가장 위험한 것은 무지가 아니다

많은 사람들은 투자에 실패하는 이유가 정보 부족 때문이라고 생각한다. 좋은 종목을 몰라서, 경제를 몰라서, 전문가가 아니라서. 그래서 투자에 성공하려면 엄청난 지식이 필요하다고 믿는다. 물론 지식은 중요하다. 하지만 투자 역사를 살펴보면 놀라운 사실을 발견하게 된다. 대부분의 투자자는 모르는 것 때문에 실패하지 않는다. 알고도 실패한다.

사람들은 "싸게 사서 비싸게 팔아야 한다"는 사실을 알고 있다. 장기투자가 중요하다는 사실도 안다. 공포에 팔면 안 된다는 사실도 안다. 그런데 실제 상황이 오면 정반대로 행동한다. 주가가 오를 때는 더 오를 것 같아서 사고, 주가가 떨어질 때는 더 떨어질 것 같아서 판다. 결국 비싸게 사고 싸게 판다. 문제는 정보가 아니다. 문제는 행동이다. 그리고 행동을 결정하는 것은 감정이다.

인간의 뇌는 투자에 불리하게 설계되어 있다

인간은 원래 투자자가 되도록 진화하지 않았다. 수십만 년 동안 인간은 생존을 위해 즉각적인 위험에 반응해야 했다. 숲속에서 맹수가 나타나면 도망쳐야 했다. 불이 나면 피해야 했다. 위험을 과장해서 인식하는 것이 생존에 유리했다.

하지만 금융시장은 다르다. 시장의 하락은 맹수가 아니다. 주가가 20% 하락했다고 해서 내일 당장 굶어 죽는 것도 아니다. 그러나 인간의 뇌는 그렇게 받아들이지 않는다. 주식 계좌가 빨간색으로 물들기 시작하면 뇌는 실제 위험과 비슷한 수준의 스트레스를 느낀다. 그래서 공포에 빠진다. 그리고 공포는 합리적인 판단을 마비시킨다. 이것이 많은 투자자들이 폭락장에서 매도하는 이유다.

닷컴버블이 남긴 교훈

1990년대 후반 미국에서는 인터넷 혁명이 시작되고 있었다. 새로운 기술이 등장했고 세상은 빠르게 변했다. 사람들은 인터넷이 미래라고 믿었다. 그 믿음 자체는 틀리지 않았다. 실제로 인터넷은 세상을 바꾸었다. 문제는 사람들이 미래를 믿은 것이 아니라 가격에 취했다는 점이다.

당시에는 기업 이름에 ".com"만 붙어도 주가가 급등했다. 매출이 없어도, 이익이 없어도, 사업 모델이 없어도 괜찮았다. 사람들은 "어차피 계속 오를 거야"라고 생각했다. 하지만 현실은 달랐다. 2000년 버블이 무너지기 시작했다. 수많은 인터넷 기업들이 사라졌다. 나스닥 지수는 약 80% 가까이 폭락했다. 당시 시장에 처음 들어온 수많은 개인 투자자들이 큰 손실을 입었다. 흥미로운 점은 이들이 바보가 아니었다는 것이다. 오히려 똑똑한 사람도 많았다. 하지만 군중심리를 이기지 못했다. 사람들이 돈을 버는 모습을 보며 뒤늦게 뛰어들었다. 그리고 결국 가장 비싼 가격에 샀다.

금융위기는 또 다른 모습을 보여주었다

2008년 금융위기는 닷컴버블과 반대였다. 이번에는 탐욕이 아니라 공포가 시장을 지배했다. 뉴스에서는 연일 경제 붕괴를 이야기했다. 대형 금융기관이 파산했다. 실업률은 치솟았다. 사람들은 현금을 들고 있어야 안전하다고 생각했다. 당시 많은 투자자들이 "이번에는 정말 다르다"고 말했다. 하지만 역사적으로 시장은 항상 비슷한 말을 들어왔다. 1929년에도, 1973년에도, 1987년에도, 2000년에도, 그리고 2008년에도 그랬다. 공포는 늘 특별해 보인다. 하지만 대부분의 경우 시장은 결국 회복했다. 문제는 많은 투자자들이 회복을 기다리지 못했다는 것이다. 그들은 최악의 시점에 매도했다. 그리고 회복이 시작된 후 다시 비싼 가격에 돌아왔다.

코로나 폭락은 인간 심리를 다시 증명했다

2020년 코로나 팬데믹은 또 하나의 실험이었다. 불과 몇 주 만에 시장은 급락했다. 도시가 봉쇄되고, 공장이 멈추고, 비행기가 멈추고, 경제 활동이 정지되었다. 당시 많은 전문가들은 장기 침체를 예상했다. 그러나 시장은 예상보다 훨씬 빠르게 회복했다. 공포에 매도한 사람들은 충격을 받았다. 그들이 시장 밖에서 기다리는 동안 시장은 다시 상승하기 시작했다. 반면 원칙을 지킨 투자자들은 회복의 수혜를 누렸다. 코로나 폭락은 중요한 사실을 다시 보여주었다. 투자 성공은 미래를 맞추는 능력이 아니라 원칙을 지키는 능력이라는 사실이다.

나의 경고

나는 투자자의 가장 큰 적이 자기 자신일 수 있다고 생각한다. 많은 사람들은 시장을 이기려고 한다. 하지만 실제로는 자기 감정을 이기는 것이 훨씬 어렵다. 시장은 우리를 강제로 매도시키지 않는다. 결정을 내리는 것은 결국 투자자 자신이다. 따라서 투자자는 시장보다 자신의 심리를 먼저 이해해야 한다. 공포에 빠질 때 어떤 행동을 하는지, 탐욕을 느낄 때 어떤 실수를 하는지 — 자신의 약점을 알아야 한다.

워런 버핏이 특별한 이유

버핏은 자신이 미래를 정확히 예측할 수 없다는 사실을 잘 알고 있다. 그래서 그는 예측보다 원칙에 의존한다. 좋은 기업, 강한 경쟁력, 건전한 재무구조, 합리적인 가격. 그는 수십 년 동안 같은 원칙을 반복했다. 시장이 공포에 빠져도 원칙을 버리지 않았다. 그의 강점은 지능보다 일관성에 있었다.

ETF 투자자도 같은 실수를 반복한다

많은 사람들은 ETF를 사면 자동으로 성공한다고 생각한다. 하지만 ETF도 결국 사람이 투자한다. ETF 투자자 역시 공포에 빠질 수 있다. 실제로 많은 투자자들이 ETF를 가장 비싼 시기에 사고 가장 싼 시기에 판다. ETF는 좋은 도구다. 하지만 도구가 사용자의 감정을 제거해 주지는 않는다. 장기 투자에 성공하려면 ETF보다 중요한 것이 있다. 바로 행동이다.

QLD 투자자가 반드시 알아야 할 것

QLD는 일반 ETF보다 변동성이 크다. 상승할 때는 빠르게 상승하지만, 하락할 때도 빠르게 하락한다. 따라서 감정에 따라 행동하는 투자자는 장기적으로 살아남기 어렵다. QLD 투자자는 하락을 예외가 아니라 과정으로 받아들여야 한다. -20%도, -30%도, -40%도, 심지어 그 이상도 가능하다. 중요한 것은 하락이 아니라 대응이다. 미리 원칙을 정해 놓은 투자자는 흔들리지 않는다. 하지만 원칙이 없는 투자자는 시장과 함께 흔들린다.

Chapter 2 핵심 정리
대부분의 투자자는 정보 부족보다 감정 때문에 실패한다.
인간의 뇌는 원래 투자에 불리하게 설계되어 있다.
닷컴버블은 탐욕의 위험성을 보여준다.
금융위기와 코로나 폭락은 공포의 위험성을 보여준다.
나는 투자자의 가장 큰 적이 자기 자신이라고 말한다.
워런 버핏의 강점은 예측 능력이 아니라 원칙을 지키는 능력이었다.
ETF 투자자도 감정을 통제하지 못하면 실패할 수 있다.
QLD 투자자는 변동성을 받아들이고 계획에 따라 행동해야 한다.

기억해야 할 문장

"시장은 당신을 망하게 하지 않는다. 공포와 탐욕에 흔들리는 당신의 행동이 당신을 망하게 한다."''',
    ),
    _BookChapter(
      title: 'Ch3. 시장',
      body: '''시장은 당신의 주인이 아니라 하인이다
매일 아침 문을 두드리는 이상한 남자

상상해 보자. 당신이 어느 훌륭한 사업체의 공동 소유주라고 가정하자. 사업은 안정적으로 성장하고 있다. 매년 매출이 늘고 있고 수익도 꾸준히 증가한다. 그런데 이상한 일이 하나 있다. 매일 아침 한 남자가 당신의 집 문을 두드린다. 그의 이름은 시장이다.

그는 매일 같은 질문을 한다. "오늘 당신의 지분을 사겠습니다." 또는 "오늘 제 지분을 사시겠습니까?" 문제는 그가 제시하는 가격이 매일 바뀐다는 것이다. 어떤 날은 지나치게 낙관적이다. 사업 전망이 밝다며 터무니없이 높은 가격을 부른다. 반면 어떤 날은 완전히 우울해져서 헐값에 팔려고 한다. 사업 자체는 아무것도 변하지 않았는데 가격만 크게 변하는 것이다.

나는 바로 이 비유를 통해 주식 시장의 본질을 설명한다. 나는 이 이상한 남자를 "시장(Mr. Market)"이라고 부른다.

대부분의 사람들은 시장을 오해한다

나에게 시장은 단순한 도구다. 하지만 대부분의 사람들은 그를 스승처럼 대한다. 시장 가격이 오르면 기뻐하고, 시장 가격이 떨어지면 불안해한다. 마치 시장이 진실을 알고 있는 것처럼 행동한다. 그러나 시장은 예언자가 아니다. 시장은 단지 가격을 제시할 뿐이다. 그 가격이 반드시 옳은 것은 아니다. 오히려 역사적으로 시장은 수없이 틀렸다.

닷컴버블 당시의 시장

1999년, 시장은 세상에서 가장 낙관적인 사람이 되었다. 인터넷이 세상을 바꿀 것이라는 믿음은 사실이었다. 문제는 그 믿음이 광기로 변했다는 것이다. 매출도 없고 수익도 없는 기업들이 수십억 달러 가치를 인정받았다. 기업 이름에 ".com"만 붙어도 주가가 폭등했다. 당시 시장은 매일 더 높은 가격을 외쳤고, 사람들은 "시장이 이렇게 평가하는데 틀릴 리가 없어"라고 생각했다. 하지만 시장은 틀렸다. 2000년 버블이 무너지자 수많은 기업들이 사라졌다. 당시의 가격은 기업 가치가 아니라 집단적 흥분을 반영한 숫자에 불과했다.

금융위기 당시의 시장

2008년이 되자 상황은 완전히 바뀌었다. 이번에는 탐욕이 아니라 공포가 시장을 지배했다. 시장은 매일 더 낮은 가격을 불렀다. 많은 투자자들은 시장이 무언가를 알고 있다고 생각해 서둘러 매도했다. 하지만 실제로는 그렇지 않았다. 우량 기업들은 여전히 제품을 팔고 있었다. 직원들은 여전히 출근하고 있었다. 달라진 것은 사람들의 감정뿐이었다. 몇 년 뒤 시장은 회복했고 새로운 최고치를 기록했다. 결국 틀린 것은 기업이 아니라 시장의 감정이었다.

코로나 폭락은 무엇을 보여주었는가

2020년 코로나 팬데믹은 시장의 또 다른 모습을 보여주었다. 불과 몇 주 만에 시장은 급락했다. 뉴스는 연일 최악의 시나리오를 이야기했고, 사람들은 현금을 들고 도망쳤다. 그 순간 시장은 완전히 공포에 빠져 있었다. 하지만 불과 몇 달 뒤 시장은 반등하기 시작했고, 1년 뒤에는 사상 최고치를 경신했다. 흥미로운 점은 기업의 본질적 가치가 그렇게 빠르게 변한 것이 아니라는 사실이다. 변한 것은 사람들의 감정이었다. 시장은 그 감정을 가격으로 표현했을 뿐이다.

워런 버핏은 왜 시장을 좋아했을까

워런 버핏은 시장을 매우 좋아했다. 하지만 대부분의 투자자들과는 이유가 달랐다. 사람들은 시장이 오르면 좋아하고 떨어지면 싫어한다. 버핏은 오히려 시장이 비합리적일수록 좋아했다. 왜냐하면 기회가 생기기 때문이다. 좋은 기업이 공포 때문에 싸게 거래된다면, 그것은 장기 투자자에게 선물과 같다. 버핏은 늘 가격과 가치를 구분했다. 시장이 낮은 가격을 제시한다고 해서 가치가 낮아지는 것은 아니라고 생각했다. 그는 시장을 참고는 했지만 절대 따르지는 않았다.

QLD 투자자에게 시장은 더욱 중요하다

QLD는 나스닥100의 약 2배 움직임을 추구한다. 따라서 시장의 감정이 더욱 극단적으로 반영된다. 나스닥이 10% 하락하면 QLD는 훨씬 크게 하락할 수 있다. 그 순간 많은 투자자들은 "이거 잘못된 것 아닌가?", "더 떨어지는 것 아닌가?", "지금이라도 팔아야 하나?"라는 생각을 한다. 하지만 이때야말로 시장의 본질을 이해해야 한다. 가격은 감정이다. 가치는 별개의 문제다. 만약 미국 기술 기업들의 장기 경쟁력이 유지되고 있다면, 가격 하락이 곧 가치 하락을 의미하는 것은 아니다. 오히려 장기 투자자에게는 더 좋은 진입 기회가 될 수도 있다.

현명한 투자자는 시장을 이용한다

대부분의 사람들은 시장에게 이용당한다. 시장이 흥분하면 함께 흥분하고, 시장이 공포에 빠지면 함께 공포에 빠진다. 하지만 나는 다르게 행동한다. 시장이 과열되면 경계하고, 시장이 공포에 빠지면 기회를 찾는다. 나는 시장의 기분을 따라가지 않는다. 시장의 기분을 활용한다. 바로 이것이 내가 말하는 시장의 진짜 의미다.

Chapter 3 핵심 정리
시장은 매일 가격을 제시하지만 항상 옳지는 않다.
가격과 가치는 서로 다르다.
닷컴버블은 시장의 탐욕을 보여준다.
금융위기와 코로나 폭락은 시장의 공포를 보여준다.
워런 버핏은 시장의 감정을 이용했다.
ETF 투자자도 시장 심리에 휘둘릴 수 있다.
QLD 투자자는 가격보다 가치에 집중해야 한다.
시장은 주인이 아니라 하인이다.

기억해야 할 문장

"시장은 당신에게 가격을 제시할 뿐이다. 그 가격을 받아들일지 말지는 당신의 선택이다."''',
    ),
    _BookChapter(
      title: 'Ch4. 안전마진',
      body: '''위대한 투자자들이 가장 먼저 생각한 것은 수익이 아니라 생존이었다
비행기에 예비 연료가 있는 이유

당신이 비행기를 타고 서울에서 뉴욕으로 간다고 가정해 보자. 조종사는 출발 전 연료를 계산한다. 서울에서 뉴욕까지 가는 데 필요한 연료를 정확하게 계산하는 것은 어렵지 않다. 그런데도 항공사는 딱 필요한 만큼만 연료를 싣지 않는다. 항상 여유분을 준비한다. 기상이 악화될 수도 있고, 공항이 혼잡할 수도 있고, 예상치 못한 문제가 발생할 수도 있기 때문이다. 만약 필요한 만큼만 연료를 실었다면 단 한 번의 변수만으로도 치명적인 결과가 발생할 수 있다.

투자도 마찬가지다. 문제는 대부분의 투자자들이 수익률에는 집착하면서 안전 여유에는 관심이 없다는 것이다. 그들은 더 높은 수익을 원하고, 더 빠른 부를 원한다. 그리고 그 과정에서 가장 중요한 것을 잊는다. 바로 생존이다.

내가 가장 중요하게 생각한 개념

이 글을 읽는 사람이라면 반드시 기억해야 할 단어가 있다. 바로 안전마진(Margin of Safety)이다. 나는 수많은 투자 원칙을 이야기하지만 결국 모든 철학은 안전마진으로 귀결된다. 나는 인간이 미래를 정확히 예측할 수 없다고 생각한다. 경제 전망도, 기업 실적 예측도, 전문가 분석도, 심지어 자신의 판단도 틀릴 수 있다. 그래서 나는 항상 질문한다. "내가 틀려도 살아남을 수 있는가?" 이 질문이 바로 안전마진의 시작이다.

왜 대부분의 투자자는 안전마진을 무시할까

이유는 단순하다. 안전마진은 지루하기 때문이다. 현금을 보유하면 수익률이 낮아 보인다. 분산투자를 하면 대박이 어려워 보인다. 레버리지를 줄이면 성장 속도가 느려 보인다. 사람들은 즉각적인 결과를 원하기 때문에 위험을 과소평가한다.

상승장에서는 특히 그렇다. 시장이 계속 오를 때는 누구나 천재처럼 보인다. 보수적인 투자자는 뒤처지는 것처럼 보이고, 현금을 가진 사람은 바보처럼 보인다. 하지만 시장은 항상 같은 방식으로 사람들을 속인다. 상승장에서는 위험이 보이지 않는다. 하락장이 와야 비로소 위험이 보인다. 그리고 그때는 이미 늦은 경우가 많다.

워런 버핏이 절대 하지 않는 것

워런 버핏은 세계 최고의 투자자 중 한 명이지만 의외로 하지 않는 것이 많다. 그는 이해하지 못하는 사업에 투자하지 않는다. 과도한 부채를 싫어한다. 전 재산을 하나의 아이디어에 걸지 않는다. 버핏이 겁이 많아서가 아니다. 그는 위험을 정확히 이해하기 때문이다.

버핏은 이런 말을 했다. "규칙 1: 돈을 잃지 마라. 규칙 2: 규칙 1을 잊지 마라." 물론 투자에서는 손실이 발생할 수 있다. 버핏이 말한 진짜 의미는 회복 불가능한 손실을 피하라는 것이다. 50% 손실이 발생하면 원금을 회복하기 위해서는 100% 상승이 필요하다. 80% 손실이 발생하면 400% 상승이 필요하다. 95% 손실이 발생하면 거의 회복이 불가능하다. 그래서 위대한 투자자들은 수익률보다 생존을 먼저 생각한다.

닷컴버블과 금융위기가 가르쳐 준 것

1999년에는 안전마진이라는 개념 자체가 무시되었다. 수익도 없는 기업들이 수십억 달러 가치를 인정받았고, 사람들은 "이번에는 다르다"고 말했다. 역사상 가장 위험한 말 중 하나다. 2000년 버블이 터졌을 때 수많은 기업들이 사라졌다. 문제는 인터넷이 아니었다. 문제는 안전마진이 없었다는 것이다.

2008년 금융위기 역시 같은 교훈을 남겼다. 당시 많은 금융기관들은 지나친 레버리지를 사용했다. 안전 여유가 없었다. 시장이 조금만 흔들려도 무너질 수 있는 구조였고, 결국 무너졌다. 반면 충분한 현금을 보유하고 있었던 기업들은 살아남았다. 심지어 위기를 기회로 활용하기도 했다. 위기는 언제나 안전마진의 중요성을 증명한다.

QLD 투자자에게 안전마진이 중요한 이유

QLD는 나스닥100의 약 2배 수익률을 추구한다. 장기적으로 높은 성장 가능성이 있지만 변동성도 크다. 그래서 안전마진이 더욱 중요하다. 만약 모든 자산을 QLD에 투자했다면, 나스닥이 큰 폭으로 하락할 경우 극심한 심리적 압박을 받게 된다. 많은 사람들이 그 순간 계획을 포기한다. 반대로 현금을 보유하고 있다면 이야기가 달라진다. 하락은 위기가 아니라 기회가 된다.

예를 들어 QLD -20%에서 소액 매수, -30%에서 현금 일부 투입, -40%에서 적극적 매수, -50%에서 장기 관점의 기회 검토 — 이런 전략은 결국 안전마진에서 출발한다. 현금은 단순한 대기 자금이 아니다. 기회를 살 수 있는 권리다.

진짜 위험은 무엇인가

많은 투자자들은 변동성을 위험이라고 생각한다. 하지만 나는 다르게 생각한다. 진짜 위험은 가격 변동이 아니다. 영구적인 자본 손실이다. 주가가 일시적으로 30% 하락하는 것은 위험이 아닐 수 있다. 하지만 공포 때문에 바닥에서 매도하는 것, 좋은 기업을 이해하지 못한 채 투자하는 것, 과도한 레버리지를 사용하는 것 — 이것이 진짜 위험이다. 안전마진이 없는 상태로 투자하는 것이 진짜 위험이다.

Chapter 4 핵심 정리
안전마진은 내 철학의 핵심이다.
미래는 예측할 수 없기 때문에 항상 여유를 두어야 한다.
수익률보다 생존이 중요하다.
워런 버핏은 위험보다 생존 확률을 먼저 본다.
닷컴버블과 금융위기는 안전마진의 중요성을 보여준다.
현금은 기회를 살 수 있는 권리다.
ETF 투자자도 안전마진이 필요하다.
QLD 투자자는 특히 현금과 규칙 기반 전략이 중요하다.

기억해야 할 문장

"훌륭한 투자자는 가장 많은 돈을 버는 사람이 아니다. 가장 오래 살아남아 복리의 힘을 누리는 사람이다."''',
    ),
    _BookChapter(
      title: 'Ch5. 군중심리와 투자',
      body: '''시장은 숫자로 움직이는 것 같지만, 결국 사람의 감정으로 움직인다
사람들은 왜 같은 실수를 반복할까

1637년 네덜란드, 튤립 한 뿌리가 집 한 채 가격에 거래되었다. 1929년 미국, 사람들은 빚을 내서 주식을 샀다. 2000년 닷컴버블, 수익이 없는 인터넷 기업들이 수십억 달러 가치를 인정받았다. 2021년 밈 주식 열풍, 실적과 관계없이 인터넷 커뮤니티의 열기에 의해 주가가 폭등했다.

시대도 다르고 나라도 다르다. 투자 대상도 다르다. 하지만 놀라울 정도로 공통점이 있다. 사람들은 언제나 같은 실수를 반복한다. 왜 그럴까? 그 이유는 시장이 숫자로 움직이는 것 같지만 실제로는 인간의 감정으로 움직이기 때문이다. 공포, 탐욕, 희망, 후회, 질투 — 이런 감정들이 모여 가격을 만든다. 그리고 투자자는 생각보다 감정에 훨씬 약하다.

인간은 원래 군중을 따라가도록 진화했다

수만 년 전 인류에게 군중을 따르는 것은 생존 전략이었다. 부족 전체가 한 방향으로 도망가는데 혼자 남는 것은 위험했다. 그래서 인간의 뇌는 본능적으로 다수의 행동을 신뢰하도록 발전했다.

문제는 금융시장이 이런 본능을 이용한다는 점이다. 시장에서 모두가 같은 방향으로 움직일 때 사람들은 강한 심리적 압박을 느낀다. 주변 사람들이 돈을 벌고 있으면 불안해지고, SNS에서 수익 인증이 넘쳐나면 조급해지고, 뉴스에서 새로운 투자 열풍을 이야기하면 뒤처지는 느낌이 든다. 이 감정을 투자 세계에서는 FOMO(Fear Of Missing Out), 기회를 놓칠 것 같은 두려움이라고 부른다. 흥미로운 점은 투자 실패의 상당수가 이 감정에서 시작된다는 사실이다.

닷컴버블이 보여준 군중심리의 힘

1999년 미국에서는 인터넷이 세상을 바꿀 것이라는 믿음이 확산되고 있었다. 사실 이 믿음 자체는 틀리지 않았다. 인터넷은 실제로 세상을 바꾸었다. 문제는 사람들이 미래의 가능성을 현실보다 훨씬 크게 평가했다는 점이다. 인터넷 기업이면 무조건 오른다고 믿었다. 기업 이름에 ".com"만 붙으면 투자자들이 몰려들었다. 사람들은 기업을 분석하지 않았다. 그저 다른 사람들이 사고 있었기 때문에 따라 샀다.

군중은 서로를 설득했다. "이번에는 다르다." "새로운 시대가 왔다." "옛날 기준으로는 설명할 수 없다." 그리고 언제나 그렇듯 시장은 현실로 돌아왔다. 버블은 붕괴되었고, 수많은 기업들이 사라졌고, 많은 투자자들이 재산 대부분을 잃었다. 군중심리는 상승장에서 가장 위험하다. 왜냐하면 그 순간에는 모두가 자신이 옳다고 믿기 때문이다.

금융위기는 공포의 군중심리를 보여주었다

닷컴버블은 탐욕의 사례였다면, 2008년 금융위기는 공포의 사례였다. 당시 사람들은 경제 시스템 자체가 무너질 것이라고 생각했다. 뉴스에서는 매일 위기 소식을 전했다. 은행이 파산하고, 실업률이 상승하고, 주가는 계속 하락했다. 많은 투자자들이 공포에 휩싸여 가장 나쁜 시점에 매도했다.

상승장에서는 군중이 탐욕스럽고, 하락장에서는 군중이 공포스럽다. 하지만 결과는 비슷하다. 둘 다 잘못된 판단을 만든다. 탐욕은 지나치게 비싼 가격에 사게 만들고, 공포는 지나치게 싼 가격에 팔게 만든다.

나의 조언

나는 시장의 감정을 이해하는 것이 중요하다고 말한다. 하지만 더 중요한 것은 감정을 따라가지 않는 것이다. 나는 투자자가 군중의 의견을 기준으로 판단해서는 안 된다고 생각한다. 대부분의 사람이 매수한다고 해서 좋은 투자도 아니고, 대부분의 사람이 매도한다고 해서 나쁜 투자도 아니다. 중요한 것은 가치다. 시장 참여자의 숫자가 아니다. 나는 독립적인 사고를 강조한다. 투자자는 스스로 판단해야 한다. 군중이 아니라 사실에 근거해야 한다.

워런 버핏은 왜 반대로 행동했을까

버핏이 특별한 이유 중 하나는 군중과 반대로 행동할 수 있었기 때문이다. 그는 시장이 과열되었을 때 흥분하지 않았다. 반대로 시장이 공포에 빠졌을 때 기회를 찾았다. 2008년 금융위기 당시 많은 투자자들이 시장을 떠날 때 버핏은 적극적으로 투자했다. 그는 다른 사람들의 감정이 아니라 기업의 가치를 보았다. 공포가 극심한 시기에 매수하는 것은 인간의 본능을 거스르는 행동이다. 하지만 장기 투자자는 본능보다 원칙을 따라야 한다. 버핏은 그것을 평생 실천했다.

QLD 투자자가 반드시 이해해야 하는 심리

QLD는 일반 ETF보다 변동성이 훨씬 크다. 따라서 군중심리의 영향을 더욱 강하게 받는다. QLD가 급등하면 "지금 안 사면 늦는다", "이번에는 계속 오른다"는 생각이 든다. 반대로 QLD가 급락하면 "더 떨어질 것 같다", "지금이라도 팔아야 하나"라는 공포가 찾아온다. 하지만 이런 감정은 과거에도 수없이 반복되었고, 앞으로도 반복될 것이다. 장기 투자자는 감정을 없애려고 하지 않는다. 대신 감정에 따라 행동하지 않는 법을 배운다. 그것이 핵심이다.

감정이 아닌 규칙으로 투자하라

군중심리를 완전히 없앨 수는 없다. 인간이기 때문이다. 하지만 영향을 줄일 수는 있다. 가장 좋은 방법은 규칙을 만드는 것이다. QLD -20%에서 소액 매수, -30%에서 현금 일부 투입, -40%에서 적극적 매수, -50%에서 계획된 비중 투자 — 이런 규칙이 있다면 감정이 개입할 공간이 줄어든다. 시장이 공포에 빠져도 행동 기준이 명확하다. 규칙은 감정의 적이다. 그리고 장기 투자자의 가장 강력한 무기이기도 하다.

Chapter 5 핵심 정리
인간은 본능적으로 군중을 따라가도록 설계되어 있다.
투자 실패의 상당수는 군중심리에서 시작된다.
닷컴버블은 탐욕의 위험성을 보여준다.
금융위기는 공포의 위험성을 보여준다.
나는 독립적인 사고를 강조한다.
워런 버핏은 군중과 반대로 행동할 수 있었다.
ETF 투자자도 군중심리에 휘둘릴 수 있다.
QLD 투자자는 규칙 기반 투자가 특히 중요하다.

기억해야 할 문장

"군중이 확신에 차 있을 때 가장 조심하라. 그리고 군중이 절망에 빠져 있을 때 가장 냉정하라."''',
    ),
    _BookChapter(
      title: 'Ch6. 시장은 왜 장기적으로 오르는가',
      body: '''폭락은 반복되지만 시장은 왜 계속 최고치를 경신하는가
"이번에는 정말 끝난 것 같다"

투자 인생에서 한 번쯤은 이런 생각을 하게 된다. 주식 시장이 폭락한다. 뉴스에서는 위기를 이야기하고, 전문가들은 경기 침체를 경고하고, 사람들은 현금을 들고 도망친다. 그리고 많은 투자자들이 같은 말을 한다. "이번에는 정말 끝난 것 같다."

흥미로운 사실은 이 말이 거의 모든 시대에 반복되었다는 것이다. 1929년 대공황, 1973년 오일쇼크, 1987년 블랙먼데이, 2000년 닷컴버블, 2008년 금융위기, 2020년 코로나 폭락 — 매번 사람들은 세상이 끝날 것처럼 이야기했다. 하지만 시장은 결국 회복했다. 그리고 더 높은 곳으로 올라갔다. 왜 그럴까?

시장은 단순한 숫자가 아니다

많은 사람들은 주식 시장을 차트로만 본다. 하지만 시장은 차트가 아니다. 시장은 경제 그 자체다. 더 정확히 말하면 수많은 기업들의 집합이다. 애플, 마이크로소프트, 엔비디아, 아마존, 메타, 구글 — 이 기업들이 매일 새로운 제품을 만들고 서비스를 개선하며 고객을 늘린다. 주가는 그 결과를 반영하는 숫자일 뿐이다. 따라서 시장이 장기적으로 상승한다는 것은 결국 기업들이 성장하고 있다는 의미다. 기업이 성장하는 한 시장도 성장한다.

인류는 끊임없이 발전해 왔다

100년 전을 생각해 보자. 당시 사람들은 스마트폰이 무엇인지 몰랐다. 인터넷도 없었다. GPS도 없었다. 인공지능은 공상과학 소설에나 등장했다. 하지만 지금 우리는 손바닥 안의 기기로 전 세계와 연결되고, 몇 초 만에 정보를 찾고, 집에서 물건을 주문하고, AI에게 질문을 한다. 인류는 끊임없이 생산성을 높여 왔다. 그리고 생산성 향상은 결국 기업 이익 증가로 이어졌다. 기업 이익이 증가하면 주가도 장기적으로 상승한다. 시장 상승의 가장 근본적인 원인은 바로 생산성 혁신이다.

역사를 보면 항상 혁신이 있었다. 1800년대에는 철도가, 1900년대에는 자동차가 세상을 바꾸었다. 전기는 산업 구조를 바꾸었고, 컴퓨터는 업무 방식을 바꾸었고, 인터넷은 정보의 흐름을 바꾸었고, 스마트폰은 생활 방식을 바꾸었다. 그리고 지금은 AI가 등장하고 있다. 물론 모든 기업이 살아남는 것은 아니다. 하지만 전체 경제는 발전한다. 시장은 그 발전의 과실을 반영한다.

위기 속에서도 시장은 성장했다

1929년 미국 대공황은 역사상 가장 심각한 경제 위기 중 하나였다. 실업률은 20%를 넘었고, 은행이 무너졌고, 수많은 사람들이 일자리를 잃었다. 당시 사람들은 자본주의 자체가 끝났다고 생각했다. 하지만 자본주의는 끝나지 않았다. 기업들은 살아남기 위해 변화했고, 새로운 산업이 등장했고, 경제는 회복했다.

많은 사람들은 닷컴버블을 실패로 기억한다. 하지만 인터넷은 실패했을까? 아니다. 인터넷은 인류 역사상 가장 강력한 혁신 중 하나가 되었다. 실패한 것은 인터넷이 아니었다. 과도한 기대였다. 버블은 무너질 수 있지만 혁신은 남는다.

2008년 금융위기 당시 사람들은 미국 경제가 무너질 것이라고 생각했다. 하지만 위기는 오히려 기업들을 더 강하게 만들었다. 비용 구조를 개선하고, 효율성을 높이고, 새로운 기술을 도입한 결과, 살아남은 기업들은 이전보다 더 강해졌다. 시장은 위기를 통해 정화되기도 한다.

나스닥이 특별한 이유

QLD 투자자라면 반드시 이해해야 하는 부분이다. 나스닥은 단순한 주가지수가 아니다. 세계에서 가장 혁신적인 기업들이 모여 있는 곳이다. 애플, 마이크로소프트, 엔비디아, 아마존, 메타, 브로드컴 — 이 기업들의 공통점은 미래를 만든다는 점이다. 기술 혁신의 중심에 있다는 점이다. 따라서 나스닥은 인류 생산성 향상의 직접적인 수혜를 받는다.

QLD를 보유한다는 것은 단순히 ETF를 보유하는 것이 아니다. 인류의 발전을 믿는 것이다. 기술 혁신을 믿는 것이다. 물론 중간에는 폭락이 오고, 버블도 오고, 공포도 온다. 하지만 장기 투자자는 그 모든 것을 포함해서 투자한다. 폭락이 없을 것이라고 믿지 않는다. 폭락이 있어도 결국 혁신은 계속될 것이라고 믿는다.

시장은 직선으로 오르지 않는다. 계단처럼 오른다. 상승, 조정, 폭락, 회복, 그리고 다시 상승 — 이 과정이 반복된다. 많은 투자자들은 폭락을 비정상이라고 생각한다. 하지만 역사적으로 폭락은 정상이다. 오히려 폭락 없는 시장이 비정상이다. 따라서 장기 투자자는 폭락을 제거하려 하지 않는다. 폭락을 포함한 상태로 투자 계획을 세운다.

Chapter 6 핵심 정리
시장은 기업 성장의 결과를 반영한다.
장기적인 시장 상승의 원인은 생산성 향상이다.
철도, 자동차, 인터넷, AI는 모두 시장 성장의 원동력이었다.
대공황, 금융위기, 코로나도 시장 상승을 멈추지 못했다.
혁신은 남고 버블은 사라진다.
나스닥은 세계 혁신 기업들의 집합체다.
QLD 투자자는 기술 혁신에 투자하는 것이다.
폭락은 예외가 아니라 시장의 일부다.

기억해야 할 문장

"시장은 위기 때문에 성장하는 것이 아니라, 위기 속에서도 계속 발전하는 인간의 능력 때문에 성장한다."''',
    ),
    _BookChapter(
      title: 'Ch7. 닷컴버블의 교훈',
      body: '''미래를 맞게 본 사람들도 돈을 잃을 수 있다
인터넷은 세상을 바꿀 것이라는 믿음

1990년대 후반, 인터넷은 세상에서 가장 뜨거운 화제였다. 오늘날 우리는 인터넷이 얼마나 중요한지 알고 있다. 온라인 쇼핑, 검색 엔진, 이메일, 클라우드, 인공지능 — 모든 것의 출발점에는 인터넷이 있었다. 따라서 당시 사람들이 인터넷의 미래를 믿었던 것은 잘못이 아니었다. 오히려 그들은 옳았다. 문제는 미래를 맞게 본 것과 투자에 성공하는 것은 전혀 다른 문제라는 점이었다.

모두가 천재가 되었던 시대

1998년부터 2000년 초까지 미국 주식시장은 광기에 가까운 상승을 경험했다. 특히 인터넷 관련 기업들은 폭발적으로 상승했다. 매출이 없어도, 이익이 없어도, 사업 모델이 불분명해도 괜찮았다. 기업 이름에 ".com"만 붙어 있으면 투자자들이 몰려들었다.

당시에는 이런 말이 유행했다. "인터넷 시대에는 옛날 방식으로 기업 가치를 평가할 수 없다." "매출보다 성장성이 중요하다." "이익은 나중에 생각하면 된다." 지금 보면 위험한 이야기처럼 들리지만 당시에는 상식처럼 받아들여졌다. 사람들은 매일 부자가 되었다. 택시 기사도, 대학생도, 직장인들도 주식을 이야기했다. 주식을 하지 않는 사람이 오히려 이상하게 보일 정도였다.

상승장이 길어질수록 사람들은 자신이 똑똑해졌다고 착각한다. 실제로는 시장이 올려준 것인데 자신의 실력이라고 믿는다. 하지만 대부분은 기업을 분석하지 않았다. 단지 가격이 오르고 있었기 때문에 매수했다. 그리고 역사적으로 "이번에는 다르다"는 말이 등장할 때마다 위험은 커졌다.

버블은 어떻게 붕괴되는가

2000년 3월, 분위기가 바뀌기 시작했다. 투자자들은 조금씩 현실을 보기 시작했다. 많은 인터넷 기업들이 여전히 돈을 벌지 못하고 있었다. 주가가 하락하기 시작했다. 처음에는 아무도 신경 쓰지 않았다. "곧 다시 오를 거야." 하지만 하락은 멈추지 않았다. 그리고 공포가 시작되었다.

상승장에서는 탐욕이 전염된다. 하락장에서는 공포가 전염된다. 매도가 매도를 부르고, 공포가 공포를 부른다. 결국 나스닥 지수는 약 80% 가까운 하락을 경험했다. 많은 투자자들이 시장을 떠났다.

닷컴버블에서 가장 중요한 교훈은 이것이다. 인터넷은 실패하지 않았다. 투자자들이 실패했다. 이 차이는 매우 중요하다. 인터넷은 이후 세상을 완전히 바꾸었다. 아마존은 세계 최대 전자상거래 기업이 되었다. 구글은 인터넷 검색의 중심이 되었다. 넷플릭스는 엔터테인먼트 산업을 바꾸었다. 혁신은 실제로 성공했다. 하지만 많은 투자자들은 그 성공을 경험하지 못했다. 왜냐하면 버블이 붕괴되는 과정에서 포기했기 때문이다.

버핏의 시각

워런 버핏은 닷컴버블 시기에 많은 비판을 받았다. 사람들은 버핏이 시대에 뒤처졌다고 생각했다. 인터넷 기업에 투자하지 않았기 때문이다. 버핏은 자신이 이해하지 못하는 사업에는 투자하지 않았다. 당시에는 이 결정이 바보처럼 보였다. 하지만 버블이 붕괴된 뒤 상황은 완전히 달라졌다. 버핏은 살아남았고, 이후에도 계속 성장했다. 그가 특별한 이유는 가장 뜨거운 시장에서도 원칙을 포기하지 않았기 때문이다.

AI 열풍과 QLD 투자자의 교훈

오늘날 많은 투자자들이 묻는다. "지금 AI 열풍은 닷컴버블과 같을까?" AI는 실제 혁신이다. 이 점은 의심의 여지가 없다. 하지만 투자자는 항상 기억해야 한다. 혁신과 투자 수익은 같은 개념이 아니다. 좋은 기술이라고 해서 반드시 좋은 투자가 되는 것은 아니다. 중요한 것은 가격이다. 혁신을 의심할 필요는 없다. 하지만 가격은 항상 의심해야 한다.

닷컴버블은 단순한 역사적 사건이 아니다. 모든 투자자가 반복해서 공부해야 하는 사례다. 왜냐하면 인간의 심리는 변하지 않기 때문이다. 앞으로도 새로운 버블이 등장할 것이다. 그리고 사람들은 또다시 "이번에는 다르다"고 말할 것이다. 버핏이라면 그 순간 닷컴버블을 떠올리며 이렇게 질문했을 것이다. "지금 혁신에 투자하고 있는가? 아니면 단지 가격 상승에 취해 있는가?"

Chapter 7 핵심 정리
인터넷 혁명은 실제였지만 버블도 실제였다.
혁신과 투자 성공은 같은 의미가 아니다.
가격과 가치는 다르다.
버블은 군중심리에서 시작된다.
워런 버핏은 가장 뜨거운 시기에도 원칙을 지켰다.
혁신은 남고 버블은 사라진다.
AI 시대에도 같은 원칙이 적용된다.
QLD 투자자는 혁신뿐 아니라 가격도 고려해야 한다.

기억해야 할 문장

"미래를 맞게 보는 것만으로는 충분하지 않다. 올바른 가격에 투자해야 한다."''',
    ),
    _BookChapter(
      title: 'Ch8. 금융위기의 교훈',
      body: '''시장이 무너진 것처럼 보일 때, 투자자는 무엇을 해야 하는가
"이번에는 정말 끝났다"

2008년 9월 15일, 미국의 거대 투자은행인 리먼 브라더스가 파산을 신청했다. 당시 사람들은 믿을 수 없었다. 158년 역사를 가진 거대한 금융회사가 하루아침에 무너진 것이다. 뉴스는 연일 충격적인 소식을 전했다. 은행들이 흔들리고, 부동산 가격이 폭락하고, 기업들은 채용을 중단했다. 실업자는 급증했고, 주식 시장은 연일 폭락했다.

전 세계 투자자들은 같은 생각을 했다. "이번에는 정말 끝난 것 같다." 많은 사람들은 자본주의 시스템 자체가 붕괴될 수 있다고 믿었다. 지금 돌아보면 과장된 생각처럼 들릴 수 있다. 하지만 당시 현장에 있던 사람들에게는 현실이었다. 공포는 언제나 논리보다 강하다.

금융위기는 어떻게 시작되었을까

흥미롭게도 금융위기는 갑자기 발생한 것이 아니었다. 위기의 씨앗은 그보다 훨씬 이전에 뿌려졌다. 미국 부동산 시장은 오랫동안 상승하고 있었다. 사람들은 집값이 절대 떨어지지 않는다고 믿기 시작했고, 은행들도 그렇게 생각했다. 신용이 부족한 사람들에게도 대출을 해주기 시작했다. "어차피 집값이 오르니까 괜찮다." 이 논리가 시장 전체를 지배했다.

처음에는 문제가 없었다. 집값은 계속 올랐고 모두가 돈을 벌었다. 하지만 그것이 문제였다. 위험이 사라진 것처럼 보였기 때문이다. 사실 위험은 사라진 것이 아니라 숨어 있었을 뿐이었다.

대부분의 사람들은 하락장을 위험하다고 생각한다. 하지만 역사적으로 가장 위험한 시기는 오히려 상승장인 경우가 많았다. 상승장에서는 경계심이 사라진다. 사람들은 빚을 늘리고, 더 많은 위험을 감수하고, 안전장치를 제거하면서 "시장이 계속 오르고 있는데 뭐가 문제야?"라고 합리화한다. 2008년 금융위기 이전에도 정확히 같은 일이 벌어졌다.

버핏의 행동

2008년 금융위기 당시 대부분의 사람들은 시장을 떠나고 있었다. 공포가 극에 달해 있었다. 그런데 워런 버핏은 다른 행동을 했다. 그는 좋은 기업을 찾고 있었다. 많은 사람들이 주식을 던질 때 그는 매수 기회를 찾고 있었다. 이것이 가능한 이유는 간단하다. 그는 시장의 감정보다 기업의 가치를 믿었기 때문이다. 그리고 실제로 위기는 지나갔다. 경제는 회복했고, 시장은 새로운 최고치를 기록했다. 버핏은 다시 한번 원칙의 힘을 증명했다.

폭락장에서 사람들은 왜 실수할까

폭락장이 오면 사람들은 미래를 비관적으로 본다. 주가가 떨어지면 더 떨어질 것 같고, 뉴스가 나쁘면 상황이 더 악화될 것처럼 느껴진다. 하지만 시장은 현재가 아니라 미래를 반영한다. 가장 큰 문제는 사람들이 미래를 가장 비관적으로 보는 시점이 종종 가장 큰 기회가 되는 시점이라는 것이다. 2008년 말, 2020년 3월 — 역사적으로 가장 큰 기회는 대부분 공포의 한가운데 있었다. 하지만 그 순간에는 아무도 그것을 기회라고 생각하지 못한다.

QLD 투자자는 금융위기를 어떻게 바라봐야 할까

QLD는 나스닥100의 약 2배 움직임을 추구한다. 따라서 금융위기 같은 상황에서는 하락폭도 더 크게 나타날 수 있다. 하지만 진짜 위험은 변동성이 아니다. 변동성에 대한 자신의 반응이다. 만약 투자자가 하락을 견디지 못하고 바닥에서 매도한다면 그것이 위험이다. 반대로 현금을 준비해 두고 계획된 전략을 실행한다면 폭락은 기회가 될 수도 있다. QLD -20%에서 분할 매수 시작, -30%에서 추가 매수, -40%에서 적극적 매수, -50%에서 장기 기회 검토 — 중요한 것은 감정이 아니라 계획이다. 위기 때 필요한 것은 예측 능력이 아니라 준비다.

금융위기는 인간 심리의 역사다. 사람들은 상승장에서 위험을 잊고, 하락장에서 희망을 잊는다. 그리고 반복적으로 같은 실수를 한다. 반면 성공적인 투자자들은 원칙을 지킨다. 공포 속에서도 냉정함을 유지한다. 시간이 지나면 그 차이는 엄청난 결과로 나타난다.

Chapter 8 핵심 정리
금융위기는 갑자기 발생한 것이 아니라 위험을 무시한 결과였다.
상승장이 오히려 가장 위험한 시기일 수 있다.
나는 안전마진의 중요성을 강조한다.
워런 버핏은 공포 속에서 기회를 찾았다.
폭락은 투자자의 심리를 시험한다.
ETF가 있어도 위기는 사라지지 않는다.
QLD 투자자는 변동성보다 자신의 행동을 관리해야 한다.
위기에서 살아남는 사람이 결국 복리의 승자가 된다.

기억해야 할 문장

"위기는 투자자를 망가뜨리기도 하지만, 준비된 투자자를 부자로 만들기도 한다."''',
    ),
    _BookChapter(
      title: 'Ch9. 코로나 폭락의 교훈',
      body: '''세상이 멈춘 것처럼 보였던 순간, 시장은 미래를 보고 있었다
아무도 예상하지 못했던 위기

2020년 초, 대부분의 투자자들은 평범한 한 해가 될 것이라고 생각했다. 미국 경제는 견조했고, 실업률은 낮았고, 기업 실적도 양호했다. 나스닥은 사상 최고치를 향해 가고 있었다. 그때 중국 우한에서 시작된 작은 뉴스가 세계를 뒤흔들기 시작했다. 처음에는 많은 사람들이 대수롭지 않게 생각했다. 과거에도 전염병은 존재했다. 곧 끝날 것이라고 생각했다.

하지만 상황은 예상보다 훨씬 빠르게 악화되었다. 국가들이 국경을 폐쇄하기 시작했다. 도시가 봉쇄되었다. 학교가 문을 닫았다. 공장이 멈추고, 비행기가 사라지고, 사람들은 집 밖으로 나가지 못했다. 현대 경제 역사상 전례 없는 상황이었다.

역사상 가장 빠른 폭락

2020년 2월 말부터 시장은 급격히 흔들리기 시작했다. 그리고 3월, 공포는 패닉으로 바뀌었다. S&P500은 불과 몇 주 만에 30% 이상 하락했다. 나스닥도 급락했다. QLD 같은 레버리지 ETF는 더욱 큰 폭으로 흔들렸다. 계좌는 매일 줄어들었고, 뉴스는 더 암울해졌다. 사람들은 끊임없이 같은 질문을 했다. "이번에는 정말 다른 것 아닐까?" "경제가 완전히 멈춘 것 아닌가?" "주식을 모두 팔아야 하나?"

이전 위기와 코로나 위기가 달랐던 점은 명확했다. 금융위기는 금융 시스템 문제였고, 닷컴버블은 기술 기업 거품 문제였다. 하지만 코로나는 경제 활동 자체를 멈춰버렸다. 식당이 문을 닫고, 항공사가 멈추고, 호텔이 비고, 사람들이 소비를 하지 못했다. 경제의 엔진이 꺼진 것처럼 보였다.

주식시장은 원래 변동성이 존재한다. 하지만 코로나 폭락은 속도가 너무 빨랐다. 대부분의 투자자들은 폭락에 적응할 시간조차 없었다. 이런 상황에서 인간의 뇌는 본능적으로 반응한다. "도망쳐야 한다." 공포는 논리를 압도한다. 많은 투자자들이 손실을 견디지 못하고 시장을 떠났다.

시장은 왜 반등했을까

코로나 폭락을 이해하기 위해서는 시장의 본질을 이해해야 한다. 시장은 현재를 반영하지 않는다. 시장은 미래를 반영한다. 2020년 3월 투자자들은 두 가지 선택을 할 수 있었다. 현재만 보는 것 — 병원은 혼잡하고, 경제는 멈추고, 사람들은 불안하다. 또는 미래를 보는 것 — 언젠가는 백신이 개발될 것이고, 경제가 재개될 것이고, 사람들은 다시 소비할 것이다. 시장은 결국 두 번째를 선택했다. 그리고 놀랍게도 시장은 경제보다 먼저 회복하기 시작했다.

버핏은 항상 같은 철학을 유지했다. 그는 미국 경제가 장기적으로 성장할 것이라고 믿었다. 그는 인류가 문제를 해결할 것이라고 믿었다. 대공황도, 세계대전도, 금융위기도 극복했다. 코로나 역시 결국 극복했다. 버핏이 믿은 것은 단기 뉴스가 아니라 인간의 적응 능력이었다.

코로나 이후 세상은 더 강해졌다

흥미롭게도 코로나는 일부 기업을 오히려 더 강하게 만들었다. 원격 근무가 확산되고, 클라우드 산업이 성장하고, 전자상거래가 폭발적으로 확대되고, AI 기술 투자도 가속화되었다. 마이크로소프트와 아마존은 더욱 성장했고, 엔비디아는 이후 AI 혁명의 중심에 서게 되었다. 위기는 항상 변화를 만든다. 그리고 변화는 새로운 기회를 만든다.

코로나 폭락은 ETF 투자자들에게 매우 중요한 교훈을 남겼다. 시장은 예상보다 더 많이 하락할 수 있다. 하지만 동시에 예상보다 더 빨리 회복할 수도 있다. 대부분의 투자자들이 회복 시점을 맞추려 하지만, 역사적으로 그것은 거의 불가능했다. 최고의 전략은 대부분 단순했다. 좋은 자산을 보유하고 버티는 것. 그리고 필요하다면 하락장에서 추가 매수하는 것.

QLD 투자자에게 코로나가 가르쳐 준 것

QLD 투자자에게 코로나 폭락은 특별한 의미가 있다. 레버리지 ETF는 공포를 더욱 크게 느끼게 만들기 때문이다. 나스닥이 하락하면 QLD는 더 크게 흔들린다. 그래서 투자자는 자신의 원칙을 시험받는다. 정말 장기 투자자인가? 정말 기술 혁신을 믿는가? 정말 계획을 지킬 수 있는가? 코로나는 이런 질문을 던졌다. 그리고 시장은 결국 답을 보여주었다. 장기적인 기술 혁신은 멈추지 않았다. 오히려 더 빨라졌다.

역사를 보면 모든 위기에는 공통점이 있다. 그 시기에는 영원히 끝나지 않을 것처럼 보인다. 하지만 결국 끝났다. 중요한 것은 위기를 예측하는 능력이 아니다. 위기 속에서도 원칙을 지키는 능력이다. 장기 투자자는 미래를 예언하지 않는다. 대신 어떤 미래가 와도 살아남을 수 있도록 준비한다.

Chapter 9 핵심 정리
코로나 폭락은 현대 역사상 가장 빠른 시장 붕괴 중 하나였다.
시장은 현재보다 미래를 반영한다.
우량 기업의 가치와 시장 가격은 다를 수 있다.
버핏은 가격과 가치를 구분하라고 강조한다.
워런 버핏은 인간의 적응 능력을 믿었다.
위기는 새로운 혁신을 가속화하기도 한다.
ETF 투자자는 시장 타이밍보다 원칙이 중요하다.
QLD 투자자는 변동성 속에서도 장기적인 기술 혁신을 바라봐야 한다.

기억해야 할 문장

"시장이 가장 어두워 보이는 순간에도 미래는 계속 만들어지고 있다."''',
    ),
    _BookChapter(
      title: 'Ch10. AI 혁명과 현재 시장',
      body: '''우리는 또 하나의 역사적 변곡점에 서 있는가
사람들은 언제나 미래를 과소평가했다

1903년, 라이트 형제가 비행기를 만들었을 때 많은 사람들은 웃었다. "사람이 하늘을 난다고?" 그것은 비현실적인 이야기처럼 들렸다. 1980년대 개인용 컴퓨터가 등장했을 때도 비슷했다. 대부분의 사람들은 컴퓨터가 일부 전문가들만 사용하는 장비가 될 것이라고 생각했다. 1990년대 인터넷도 마찬가지였다. 많은 사람들은 인터넷이 단순한 유행이라고 생각했다.

하지만 역사는 반복해서 같은 사실을 보여주었다. 인간은 단기적인 변화는 과대평가하고, 장기적인 변화는 과소평가한다. 그리고 지금 우리는 또 하나의 거대한 변화 앞에 서 있다. 바로 인공지능(AI)이다.

AI는 왜 특별한가

과거의 기술 혁신들은 대부분 인간의 육체 노동을 도와주었다. 증기기관은 힘든 일을 대신했고, 자동차는 이동을 도와주었고, 컴퓨터는 계산을 도와주었고, 인터넷은 정보 전달을 도와주었다. 하지만 AI는 조금 다르다. AI는 인간의 지적 노동을 도와준다. 글을 쓰고, 번역을 하고, 분석을 하고, 코드를 작성하고, 이미지를 만들고, 심지어 의사결정을 보조하기도 한다. 이것은 단순한 기술 발전이 아니다. 생산성 혁명의 시작일 수도 있다.

주식 시장이 장기적으로 상승하는 이유는 결국 생산성 때문이다. 한 사람이 더 많은 가치를 창출할 수 있게 되면 기업 이익이 증가한다. 기업 이익이 증가하면 기업 가치가 증가한다. 그리고 결국 주가가 상승한다. 산업혁명, 전기, 컴퓨터, 인터넷 — 모두 생산성을 높였다. AI 역시 같은 길을 걷고 있다. 따라서 장기 투자자는 단순히 AI 기업에 투자하는 것이 아니라 생산성 혁명에 투자하는 것이다.

닷컴버블과 AI는 같은 것일까

많은 투자자들이 묻는다. "지금 AI 열풍은 닷컴버블 아닌가요?" 정답은 단순하지 않다. AI는 실제 혁신이다. 마찬가지로 인터넷도 실제 혁신이었다. 문제는 기술과 주가가 항상 같은 속도로 움직이지 않는다는 것이다. 닷컴버블 당시 인터넷은 진짜였지만, 일부 기업의 가격은 비현실적이었다. 오늘날 AI도 비슷한 위험이 존재할 수 있다. 좋은 기술이 반드시 좋은 투자 수익을 의미하는 것은 아니다. 내가 강조한 이유도 여기에 있다. 혁신을 믿는 것과 아무 가격에나 투자하는 것은 전혀 다른 이야기다.

엔비디아가 상징하는 것

2020년대 AI 혁명을 이야기할 때 가장 먼저 떠오르는 기업은 엔비디아다. 불과 몇 년 전만 해도 엔비디아는 게임 그래픽카드 회사라는 인식이 강했다. 하지만 AI 시대가 열리면서 상황은 완전히 달라졌다. 엔비디아의 GPU는 AI 산업의 핵심 인프라가 되었다. 전 세계 기업들이 AI 모델을 개발하기 위해 엔비디아 칩을 구매하기 시작했다. 중요한 것은 주가가 아니다. AI가 실제 경제 활동에 영향을 미치기 시작했다는 사실이다.

버핏은 늘 새로운 기술에 신중했다. 그는 이해할 수 있는 기업에 집중했고, 유행을 쫓지 않았다. 기업의 경쟁력과 수익 창출 능력을 보았다. 그래서 언제나 같은 질문을 던졌다. "이 가격은 합리적인가?" "기대가 지나치게 반영된 것은 아닌가?" "안전마진은 존재하는가?" 이것이 버핏 투자 철학의 핵심이다.

AI 시대의 ETF 투자와 QLD

대부분의 개인 투자자는 AI 산업의 최종 승자를 맞추기 어렵다. 10년 뒤 어떤 기업이 가장 강할지 정확히 예측하는 것은 거의 불가능하다. 그래서 ETF가 중요하다. ETF는 특정 기업이 아니라 산업 전체의 성장에 참여하게 해준다. 나스닥100에는 AI 혁명의 핵심 기업들이 다수 포함되어 있다. 애플, 마이크로소프트, 엔비디아, 아마존, 메타, 브로드컴 — 이들은 모두 AI 혁명의 수혜를 받을 가능성이 높다. ETF 투자자는 개별 승자를 맞추는 부담 없이 혁신의 흐름에 참여할 수 있다.

QLD 투자자에게 AI는 매우 중요한 주제다. QLD는 나스닥100의 약 2배 움직임을 추구하기 때문이다. AI 혁명이 성공할수록 QLD는 큰 수혜를 받을 가능성이 있다. 하지만 동시에 기대가 과열되면 변동성도 커질 수 있다. 그래서 장기 투자자는 두 가지를 동시에 기억해야 한다. 첫째, AI는 실제 혁신일 가능성이 높다. 둘째, 시장은 단기적으로 과열될 수 있다.

많은 투자자들은 AI가 어디까지 발전할지 예측하려고 한다. 하지만 역사적으로 가장 성공적인 투자자들은 미래를 정확히 예측한 사람들이 아니었다. 그들은 변화의 방향을 이해한 사람들이었다. 중요한 것은 내일의 주가가 아니다. 향후 10년, 20년 동안 생산성이 어떻게 변할지를 생각하는 것이다. AI의 진짜 가치는 새로운 제품이 아니다. 생산성 향상이다. 더 적은 시간으로 더 많은 일을 할 수 있게 만드는 것이다. 인류 역사를 돌아보면 생산성 혁명은 항상 경제 성장을 이끌었다. 장기 투자자는 바로 여기에 투자하는 사람이다.

Chapter 10 핵심 정리
AI는 단순한 유행이 아니라 생산성 혁명일 가능성이 높다.
시장은 장기적으로 생산성 향상을 반영한다.
닷컴버블의 교훈은 혁신과 가격을 구분하라는 것이다.
엔비디아는 AI 혁명의 대표 사례다.
나는 항상 가격과 안전마진을 강조한다.
워런 버핏은 유행보다 경쟁력을 본다.
ETF는 AI 혁명에 참여하는 효율적인 방법이 될 수 있다.
QLD 투자자는 AI 혁명의 수혜와 변동성을 동시에 이해해야 한다.

기억해야 할 문장

"위대한 투자자는 미래를 정확히 예측하는 사람이 아니라, 미래를 만들어가는 변화에 꾸준히 참여하는 사람이다."''',
    ),
