  static const _englishChapters = <_BookChapter>[
    _BookChapter(
      title: 'Ch1. Investing vs. Speculation',
      body: '''Is everyone who enters the market an investor?

The dot-com bubble was an era when any stock with the word "internet" attached to it would rise. Some companies had no revenue, no profit, and even unclear business models. Yet investors were euphoric. Prices climbed every day. The media churned out stories of new millionaires. College students spent more time on stock forums than in classrooms, and office workers debated tickers every lunch break.

At the time, many people thought of themselves as investors. But looking back, I would say this: they were not investors. They were speculators.

When the bubble collapsed in 2000, countless companies disappeared. Losses of dozens of percent occurred overnight, and many people lost the savings of a lifetime. The striking thing is that most of those who lost money could not properly explain what they had bought. They did not buy a company — they bought price appreciation. That is exactly the difference between investing and speculation.

Investing and Speculation Are Completely Different Games

Most people think of investing and speculation as similar things. Some believe buying stocks is investing, while buying crypto is speculation. But I think about it entirely differently. I define investing as needing to satisfy three conditions.

First, there must be thorough analysis. Second, principal protection must be considered. Third, a satisfactory return must be expected. Anything that fails to meet these conditions, I define as speculation.

What matters is not what you buy. What matters is the mindset with which you buy. Even buying Apple stock is speculation if the reason is "I think it'll go up tomorrow." Conversely, even buying an ETF is closer to investing if it results from analyzing a company's growth potential and long-term economic development. It is not the product that divides investing from speculation. It is the way of thinking.

Prices Change Every Day, but Value Changes Slowly

People new to the stock market mostly focus on price. How many percent did it rise today, how much profit did I make this week, what stocks are others buying? But investors look at value, not price.

Consider an example. Suppose you own a building in Gangnam, Seoul. One day someone comes and offers to buy it for 5 billion won. The next day someone offers 4 billion won. A week later someone offers 5.5 billion won again. Nothing about the building itself has changed. The rent is the same. The location is the same. The building's value has not changed much. Only the offered price has changed.

Stocks are the same. Market prices move every day. But a company's value does not change that quickly. Investors look at value. Speculators look only at price.

Humans Are Naturally Drawn to Speculation

The reason investing is difficult is human instinct. People dislike getting rich slowly. The story of maintaining a 10% annual return for 20 years is boring. But the story of a stock that rose 300% in a month is exciting. So people are naturally drawn to speculation.

Our brains are designed to prefer immediate rewards. We get more excited about the possibility of making 100% tomorrow than about making 1% today. The problem is that the market constantly exploits this psychology.

In a bull market, everyone looks like a genius. Any stock you buy goes up. The people around you are making money. Social media is full of profit screenshots. At that moment, investors unconsciously start thinking: "Am I the only one falling behind?" From that moment on, analysis disappears and emotion begins to dominate investment decisions.

Why Did Warren Buffett Get Rich?

Many people think Warren Buffett possesses extraordinary investment skills. That is true, of course. But his most powerful weapon is not stock-picking ability. It is time.

Buffett found good companies from a young age and held them for a long time. He did not try to predict tomorrow's stock price. He did not try to guess next month's interest rate. He did not try to forecast next quarter's earnings. He focused on a simple question: "Will this company still be strong in 10 years?" "Will it still be alive in 20 years?" This question changed his life. In fact, most of Buffett's wealth was created after the age of 60. Because he gave compound interest enough time to work. Speculators think of time as an enemy. Investors make time their friend.

Why ETFs Matter to the Modern Investor

When I first started learning about investing, most products were mutual funds. But today's individual investor has a far more favorable environment. ETFs like QQQ, SPY, VOO, and QLD exist. These products allow automatic diversification across dozens or hundreds of companies.

But one thing has not changed. ETFs can be used for investing, and they can also be used for speculation. If you stare at the price every day, an ETF also becomes a speculative tool. Conversely, if you approach it with the perspective of participating in long-term economic growth, it becomes an excellent investment vehicle.

What Does a QLD Investor Invest In?

Many people think of QLD as simply a leveraged ETF. But that is only half the story. QLD seeks approximately 2x the return of the Nasdaq 100. In other words, holding QLD is not merely holding an ETF — it is participating in American technological innovation. Apple, Microsoft, Nvidia, Amazon, Meta, Broadcom — if you believe these companies will continue to grow, QLD can be an investment target. But if the reason for approaching it is simply "I think it'll rise next month," that is nothing more than speculation. Same product, different mindset. The outcome is completely different.

The Investor's Greatest Enemy

Novice investors fear the market. They fear crashes. They fear economic crises. But over time, you come to understand who the real enemy is. The investor's greatest enemy is not the market. It is yourself. Fear, greed, impatience, regret, envy — these emotions push countless investors out of the market. Markets often eventually recover. But investors broken by fear do not recover. That is why the essence of investing is not stock selection. It is psychological management.

Chapter 1 Summary
Investing and speculation are completely different.
Investors buy value; speculators buy price.
Prices change every day, but value changes slowly.
Human nature likes speculation.
Buffett's greatest weapon was not prediction but time.
ETFs can be either an investment or a speculation tool.
QLD should be approached as a long-term investment in American technological innovation.
The investor's greatest enemy is not the market but one's own emotions.

A Sentence to Remember

"Investing is not a game of predicting the future. It is the process of buying good assets at a reasonable price and giving them enough time."''',
    ),
    _BookChapter(
      title: 'Ch2. Why Most Investors Fail',
      body: '''The market is not difficult. But human emotions are.

The Most Dangerous Thing Is Not Ignorance

Many people believe the reason they fail at investing is a lack of information. They didn't know the good stocks, didn't understand the economy, weren't experts. So they believe that succeeding at investing requires enormous knowledge. Knowledge is important, of course. But when you look at investment history, you discover a surprising fact. Most investors fail not because of what they don't know. They fail knowing full well what they should do.

People know they should "buy low and sell high." They know long-term investing is important. They know they shouldn't sell in panic. Yet when the real situation arrives, they do the exact opposite. When prices rise they buy because they think it will rise more, and when prices fall they sell because they think it will fall more. In the end they buy high and sell low. The problem is not information. The problem is behavior. And what determines behavior is emotion.

The Human Brain Is Designed to Work Against Investing

Humans were not originally evolved to be investors. For hundreds of thousands of years, humans needed to react immediately to threats to survive. When a predator appeared in the forest, they had to run. When fire broke out, they had to flee. Exaggerating the perception of danger was advantageous for survival.

But financial markets are different. A market decline is not a predator. A 20% drop in stocks does not mean you'll starve tomorrow. But the human brain does not accept that. When a brokerage account starts turning red, the brain feels a level of stress similar to a real physical danger. So it falls into fear. And fear paralyzes rational judgment. This is why so many investors sell during crashes.

The Lesson of the Dot-com Bubble

In the late 1990s in America, an internet revolution was beginning. New technologies appeared and the world changed rapidly. People believed the internet was the future. That belief itself was not wrong. The internet actually changed the world. The problem was that people were not just believing in the future — they were intoxicated by prices.

At the time, stocks surged simply because ".com" was added to a company name. No revenue, no profit, no business model was fine. People thought, "It'll keep rising anyway." But reality was different. In 2000 the bubble began to collapse. Countless internet companies disappeared. The Nasdaq fell nearly 80%. Many individual investors who had just entered the market suffered enormous losses. The interesting thing is that these people were not foolish. Many were actually intelligent. But they could not overcome herd psychology. They jumped in late watching others make money. And in the end they bought at the highest price.

The Financial Crisis Showed a Different Face

The 2008 financial crisis was the opposite of the dot-com bubble. This time, it was not greed but fear that dominated the market. The news talked about economic collapse every day. Major financial institutions went bankrupt. Unemployment soared. People thought holding cash was safe. Many investors at the time said, "This time is really different." But historically, markets have always heard similar words. In 1929, in 1973, in 1987, in 2000, and in 2008. Fear always looks special. But in most cases, the market eventually recovered. The problem was that many investors could not wait for the recovery. They sold at the worst point. And after the recovery started, they came back at higher prices.

The COVID Crash Proved Human Psychology Again

The 2020 COVID pandemic was yet another experiment. The market fell sharply in just a few weeks. Cities were locked down, factories stopped, planes grounded, economic activity halted. Many experts at the time predicted a prolonged recession. But the market recovered far faster than expected. People who sold in fear were shocked. While they waited outside the market, it started rising again. Meanwhile, investors who stuck to their principles reaped the rewards of recovery. The COVID crash showed an important truth again. Investment success is not the ability to predict the future — it is the ability to stick to principles.

My Warning

I believe the investor's greatest enemy can be oneself. Many people try to beat the market. But in reality, beating your own emotions is far harder. The market does not force you to sell. It is always the investor who makes the decision. Therefore, investors must understand their own psychology before the market. You must know your own weaknesses — what you do when gripped by fear, what mistakes you make when feeling greedy.

Why Buffett Is Special

Buffett knows very well that he cannot accurately predict the future. So he relies on principles rather than predictions. Good businesses, strong competitive advantages, sound financials, reasonable prices. He has repeated the same principles for decades. He did not abandon his principles even when the market fell into fear. His strength lies in consistency more than intelligence.

ETF Investors Repeat the Same Mistakes

Many people think buying an ETF guarantees success. But ETFs are ultimately bought by people. ETF investors can also fall into fear. In fact, many investors buy ETFs at the most expensive times and sell at the cheapest times. ETFs are good tools. But tools don't eliminate the user's emotions. To succeed at long-term investing, there is something more important than ETFs. It is behavior.

What QLD Investors Must Know

QLD has greater volatility than regular ETFs. It rises fast when rising, but also falls fast when falling. Therefore, investors who act on emotion will find it difficult to survive in the long run. QLD investors must accept decline not as an exception but as a process. -20%, -30%, -40%, and even more is possible. What matters is not the decline itself, but the response to it. Investors who have set principles in advance will not waver. But investors without principles will sway with the market.

Chapter 2 Summary
Most investors fail because of emotion rather than lack of information.
The human brain is originally designed to work against investing.
The dot-com bubble shows the danger of greed.
The financial crisis and COVID crash show the danger of fear.
The investor's greatest enemy is oneself.
Buffett's strength was the ability to stick to principles, not prediction.
ETF investors can also fail if they cannot control their emotions.
QLD investors must accept volatility and act according to a plan.

A Sentence to Remember

"It is not the market that ruins you. It is your own actions, swayed by fear and greed, that ruin you."''',
    ),
    _BookChapter(
      title: 'Ch3. The Market',
      body: '''The market is not your master — it is your servant.

The Strange Man Who Knocks Every Morning

Imagine you are a co-owner of a fine business. The business is growing steadily. Revenue increases every year and profits grow consistently. But there is one strange thing. Every morning a man knocks on your door. His name is the Market.

He asks the same question every day. "I'll buy your stake today." Or, "Would you like to buy my stake today?" The problem is that the price he offers changes every day. On some days he is excessively optimistic, calling out an absurdly high price claiming the business outlook is bright. On other days he is completely depressed and wants to sell at a bargain price. The business itself hasn't changed at all, yet only the price changes dramatically.

I use this analogy to explain the nature of the stock market. I call this strange man "the Market."

Most People Misunderstand the Market

To me, the market is simply a tool. But most people treat it like a teacher. When market prices rise they rejoice, and when market prices fall they become anxious. As if the market knows the truth. But the market is not a prophet. The market merely offers a price. That price is not necessarily correct. In fact, historically the market has been wrong countless times.

The Market During the Dot-com Bubble

In 1999, the market became the most optimistic person in the world. The belief that the internet would change the world was true. The problem was that this belief turned into madness. Companies with no revenue and no profit were valued at billions of dollars. Simply adding ".com" to a company name sent the stock price soaring. At the time, the market cried out ever-higher prices each day, and people thought, "The market values it this way, so it can't be wrong." But the market was wrong. When the bubble collapsed in 2000, countless companies disappeared. The prices of that time were nothing but numbers reflecting collective excitement, not company value.

The Market During the Financial Crisis

By 2008, the situation had completely changed. This time fear, not greed, dominated the market. The market called out ever-lower prices every day. Many investors thought the market knew something and rushed to sell. But that was not actually the case. Quality companies were still selling their products. Employees were still going to work. All that had changed was people's emotions. A few years later the market recovered and hit new highs. In the end, it was not the companies that were wrong — it was the market's emotions.

What Did the COVID Crash Show?

The 2020 COVID pandemic showed yet another face of the market. The market plunged in just a few weeks. The news talked about worst-case scenarios every day, and people fled with cash. At that moment, the market was completely consumed by fear. But just a few months later the market began to rebound, and a year later it broke all-time highs. The interesting point is that the intrinsic value of companies did not change that quickly. What changed was people's emotions. The market merely expressed those emotions through price.

Why Did Warren Buffett Love the Market?

Warren Buffett loved the market very much. But for different reasons than most investors. People like it when the market goes up and dislike it when it goes down. Buffett actually liked it more when the market was irrational. Because opportunities arise. If a good company is trading cheaply because of fear, that is a gift for long-term investors. Buffett always distinguished between price and value. He believed that a low price offered by the market does not mean low value. He referred to the market but never followed it.

The Market Matters Even More for QLD Investors

QLD seeks approximately 2x the movement of the Nasdaq 100. Therefore, the market's emotions are reflected even more extremely. If the Nasdaq falls 10%, QLD can fall much more. At that moment many investors think: "Is something wrong with this?" "Is it going to fall further?" "Should I sell now?" But this is precisely the time to understand the nature of the market. Price is emotion. Value is a separate matter. If the long-term competitiveness of American tech companies is being maintained, a price decline does not necessarily mean a value decline. For long-term investors, it may even be a better entry opportunity.

The Wise Investor Uses the Market

Most people are used by the market. They get excited when the market gets excited, and fall into fear when the market falls into fear. But I act differently. When the market overheats, I am cautious; when the market falls into fear, I look for opportunity. I do not follow the market's mood. I take advantage of the market's mood. This is the true meaning of what I call the market.

Chapter 3 Summary
The market offers prices every day, but is not always right.
Price and value are different from each other.
The dot-com bubble shows the market's greed.
The financial crisis and COVID crash show the market's fear.
Buffett exploited the market's emotions.
ETF investors can also be swayed by market psychology.
QLD investors must focus on value rather than price.
The market is a servant, not a master.

A Sentence to Remember

"The market only offers you a price. Whether to accept that price is your choice."''',
    ),
    _BookChapter(
      title: 'Ch4. Margin of Safety',
      body: '''The great investors thought about survival before profit.

Why Planes Carry Reserve Fuel

Suppose you are flying from Seoul to New York. The pilot calculates fuel before departure. Calculating the exact fuel needed to fly from Seoul to New York is not difficult. Yet airlines do not load only exactly what is needed. They always prepare a reserve. Because weather may deteriorate, the airport may be congested, or unexpected problems may arise. If only the exact amount of fuel were loaded, a single variable could have fatal consequences.

Investing is the same. The problem is that most investors obsess over returns while showing no interest in a safety margin. They want higher returns and faster wealth. And in the process they forget the most important thing. Survival.

The Concept I Consider Most Important

There is a word that anyone reading this must remember. It is the Margin of Safety. I talk about many investment principles, but ultimately all philosophy comes back to the margin of safety. I believe no human can predict the future precisely. Economic forecasts, earnings projections, expert analysis, and even your own judgment can be wrong. So I always ask: "Can I survive even if I am wrong?" This question is the beginning of the margin of safety.

Why Do Most Investors Ignore the Margin of Safety?

The reason is simple. The margin of safety is boring. Holding cash makes your return look low. Diversifying makes big wins seem harder. Reducing leverage makes growth look slower. People want immediate results, so they underestimate risk.

This is especially true in bull markets. When the market keeps rising, everyone looks like a genius. Conservative investors look like they're falling behind, and people holding cash look foolish. But the market always deceives people the same way. In a bull market, risks are invisible. It is only when a bear market arrives that risks become visible. And by then it is often too late.

What Buffett Never Does

Warren Buffett is one of the world's greatest investors, but surprisingly there are many things he does not do. He does not invest in businesses he does not understand. He dislikes excessive debt. He does not put his entire fortune on a single idea. Not because Buffett is timid. Because he understands risk precisely.

Buffett said this: "Rule No. 1: Never lose money. Rule No. 2: Never forget Rule No. 1." Of course, losses can occur in investing. The real meaning of what Buffett said is to avoid unrecoverable losses. If a 50% loss occurs, you need a 100% gain to recover the principal. If an 80% loss occurs, you need a 400% gain. If a 95% loss occurs, recovery is nearly impossible. That is why great investors think about survival before returns.

What the Dot-com Bubble and Financial Crisis Taught

In 1999, the concept of a margin of safety was ignored entirely. Companies with no profit were valued at billions of dollars, and people said "this time is different." One of the most dangerous phrases in history. When the bubble burst in 2000, countless companies disappeared. The problem was not the internet. The problem was there was no margin of safety.

The 2008 financial crisis left the same lesson. Many financial institutions at the time used excessive leverage. There was no safety margin. The structure was such that even a slight market wobble could cause collapse — and it did. On the other hand, companies holding sufficient cash survived. Some even turned the crisis into an opportunity. Crises always prove the importance of the margin of safety.

Why the Margin of Safety Matters for QLD Investors

QLD seeks approximately 2x the return of the Nasdaq 100. There is strong long-term growth potential, but volatility is also high. That is why the margin of safety matters even more. If all assets were invested in QLD, an extreme psychological burden would arise if the Nasdaq falls sharply. Many people abandon their plan at that moment. If you hold cash, however, the story changes. A decline becomes not a crisis but an opportunity.

For example: buying a small amount at QLD -20%, investing some cash at -30%, buying aggressively at -40%, reviewing long-term opportunities at -50% — such a strategy ultimately starts from the margin of safety. Cash is not simply idle money. It is the right to buy opportunity.

What Is Real Risk?

Many investors think of volatility as risk. But I think differently. Real risk is not price fluctuation. It is permanent capital loss. A temporary 30% drop in stock price may not be a risk. But selling at the bottom out of fear, investing without understanding a good company, using excessive leverage — these are real risks. Investing without a margin of safety is the real risk.

Chapter 4 Summary
The margin of safety is the core of my philosophy.
Because the future cannot be predicted, always leave room.
Survival matters more than returns.
Buffett looks at survival probability before risk.
The dot-com bubble and financial crisis show the importance of margin of safety.
Cash is the right to buy opportunity.
ETF investors also need a margin of safety.
QLD investors especially need cash and rules-based strategy.

A Sentence to Remember

"A great investor is not the one who earns the most money. It is the one who survives longest and enjoys the power of compounding."''',
    ),
    _BookChapter(
      title: 'Ch5. Herd Psychology and Investing',
      body: '''The market seems to move on numbers, but ultimately it moves on human emotion.

Why Do People Repeat the Same Mistakes?

In 1637 in the Netherlands, a single tulip bulb traded for the price of a house. In 1929 in America, people borrowed money to buy stocks. In the 2000 dot-com bubble, internet companies with no revenue were valued at billions of dollars. In the 2021 meme stock frenzy, stock prices soared driven by internet community enthusiasm regardless of performance.

The era is different and the country is different. The investment targets are different. But there are remarkably common threads. People always repeat the same mistakes. Why? Because even though the market seems to move on numbers, it actually moves on human emotion. Fear, greed, hope, regret, envy — these emotions gather to create prices. And investors are far more vulnerable to emotion than they think.

Humans Evolved to Follow the Crowd

Tens of thousands of years ago, following the crowd was a survival strategy for humanity. It was dangerous to be left alone while the entire tribe ran in one direction. So the human brain developed to instinctively trust the behavior of the majority.

The problem is that financial markets exploit this instinct. When everyone moves in the same direction in the market, people feel strong psychological pressure. If the people around you are making money, you become anxious; if profit screenshots overflow social media, you feel impatient; if the news talks about a new investment craze, you feel like you're falling behind. This emotion is called FOMO (Fear Of Missing Out) in the investment world. The interesting thing is that a significant number of investment failures start from this emotion.

The Power of Herd Psychology Shown by the Dot-com Bubble

In 1999 in America, the belief that the internet would change the world was spreading. In fact this belief was not wrong. The internet actually changed the world. The problem was that people valued the possibilities of the future far beyond reality. They believed internet companies would rise no matter what. Investors flocked to anything with ".com" in the name. People did not analyze companies. They simply bought because others were buying.

The crowd convinced each other. "This time is different." "A new era has come." "The old standards can't explain this." And as always, the market returned to reality. The bubble collapsed, countless companies disappeared, and many investors lost most of their wealth. Herd psychology is most dangerous in a bull market. Because at that moment, everyone believes they are right.

The Financial Crisis Showed the Herd Psychology of Fear

If the dot-com bubble was a case of greed, the 2008 financial crisis was a case of fear. People at the time believed the economic system itself might collapse. The news delivered crisis news every day. Banks went bankrupt, unemployment rose, stock prices kept falling. Many investors were swept up in fear and sold at the worst possible time.

In a bull market the crowd is greedy, and in a bear market the crowd is fearful. But the result is similar. Both lead to wrong judgments. Greed makes you buy at excessively high prices, and fear makes you sell at excessively low prices.

My Advice

I say understanding the market's emotions is important. But what is more important is not following the emotions. I believe investors should not judge based on the opinions of the crowd. A stock is not a good investment just because most people are buying, and it is not a bad investment just because most people are selling. What matters is value. Not the number of market participants. I emphasize independent thinking. Investors must judge for themselves. Based on facts, not crowds.

Why Did Warren Buffett Act the Opposite?

One reason Buffett is special is that he was able to act contrary to the crowd. He did not get excited when the market overheated. Conversely, he looked for opportunities when the market fell into fear. During the 2008 financial crisis, when many investors were leaving the market, Buffett invested aggressively. He looked at the value of companies, not the emotions of others. Buying when fear is extreme goes against human instinct. But long-term investors must follow principles over instinct. Buffett practiced that for his entire life.

The Psychology QLD Investors Must Understand

QLD has far greater volatility than regular ETFs. Therefore, it is affected far more strongly by herd psychology. When QLD surges, thoughts arise: "If I don't buy now I'll be too late," "This time it'll keep going up." Conversely, when QLD plunges, fear arrives: "I think it'll fall further," "Should I sell now?" But these emotions have been repeated countless times in the past and will be repeated in the future. Long-term investors do not try to eliminate emotion. Instead, they learn not to act on emotion. That is the key.

Invest by Rules, Not Emotions

Herd psychology cannot be completely eliminated. Because we are human. But its influence can be reduced. The best method is to create rules. Buying a small amount at QLD -20%, investing some cash at -30%, buying aggressively at -40%, investing a planned proportion at -50% — with such rules, there is less room for emotion to intervene. Even when the market falls into fear, the basis for action is clear. Rules are the enemy of emotion. And also the most powerful weapon of the long-term investor.

Chapter 5 Summary
Humans are instinctively designed to follow the crowd.
A significant number of investment failures start from herd psychology.
The dot-com bubble shows the danger of greed.
The financial crisis shows the danger of fear.
I emphasize independent thinking.
Warren Buffett was able to act contrary to the crowd.
ETF investors can also be swayed by herd psychology.
Rules-based investing is especially important for QLD investors.

A Sentence to Remember

"Be most careful when the crowd is full of conviction. And be most clear-headed when the crowd is in despair."''',
    ),
    _BookChapter(
      title: 'Ch6. Why Markets Rise in the Long Run',
      body: '''Crashes repeat, but why does the market keep hitting new highs?

"This Time It Really Feels Like the End"

At some point in an investing life, you will have this thought. The stock market crashes. The news talks about crisis, experts warn of recession, and people flee with cash. And many investors say the same thing: "This time it really feels like the end."

The interesting fact is that this phrase has been repeated in almost every era. The 1929 Great Depression, the 1973 oil shock, the 1987 Black Monday, the 2000 dot-com bubble, the 2008 financial crisis, the 2020 COVID crash — every time people spoke as if the world were ending. But the market eventually recovered. And it climbed to higher places. Why?

The Market Is Not Just Numbers

Many people look at the stock market only as a chart. But the market is not a chart. The market is the economy itself. More precisely, it is a collection of countless companies. Apple, Microsoft, Nvidia, Amazon, Meta, Google — these companies make new products, improve services, and grow their customer base every day. A stock price is merely a number reflecting that result. Therefore, the market rising in the long run ultimately means companies are growing. As long as companies grow, the market grows.

Humanity Has Continuously Advanced

Think about 100 years ago. People at that time did not know what a smartphone was. There was no internet. No GPS. Artificial intelligence appeared only in science fiction novels. But now we are connected to the entire world through a device in the palm of our hand, find information in seconds, order goods from home, and ask questions to AI. Humanity has continuously increased productivity. And productivity gains have ultimately led to increased corporate profits. When corporate profits increase, stock prices also rise in the long run. The most fundamental cause of market growth is productivity innovation.

Throughout history, there has always been innovation. In the 1800s, railways changed the world; in the 1900s, automobiles changed it. Electricity changed industrial structure, computers changed work methods, the internet changed information flow, and smartphones changed lifestyles. And now AI is emerging. Of course, not every company survives. But the overall economy advances. The market reflects that advancement.

The Market Grew Even Through Crisis

The 1929 Great Depression was one of the most serious economic crises in history. Unemployment exceeded 20%, banks collapsed, and countless people lost their jobs. At the time, people thought capitalism itself was finished. But capitalism was not finished. Companies changed to survive, new industries emerged, and the economy recovered.

Many people remember the dot-com bubble as a failure. But did the internet fail? No. The internet became one of the most powerful innovations in human history. What failed was not the internet. It was excessive expectations. Bubbles may collapse, but innovation remains.

During the 2008 financial crisis, people thought the American economy would collapse. But the crisis actually made companies stronger. By improving cost structures, increasing efficiency, and adopting new technology, companies that survived became stronger than before. The market is also purified through crisis.

Why the Nasdaq Is Special

This is something QLD investors must understand. The Nasdaq is not simply a stock index. It is where the world's most innovative companies gather. Apple, Microsoft, Nvidia, Amazon, Meta, Broadcom — these companies share the common trait of building the future. They are at the center of technological innovation. Therefore, the Nasdaq directly benefits from the improvement of human productivity.

Holding QLD is not simply holding an ETF. It is believing in human advancement. It is believing in technological innovation. Of course, along the way there will be crashes, bubbles, and fear. But long-term investors invest including all of that. They do not believe there will be no crashes. They believe that even with crashes, innovation will continue.

The market does not rise in a straight line. It rises like stairs. Rise, correction, crash, recovery, and rise again — this process repeats. Many investors think of crashes as abnormal. But historically, crashes are normal. Rather, a market without crashes is abnormal. Therefore, long-term investors do not try to eliminate crashes. They make investment plans that include crashes.

Chapter 6 Summary
The market reflects the result of corporate growth.
The cause of long-term market growth is productivity improvement.
Railways, automobiles, the internet, and AI have all been drivers of market growth.
The Great Depression, financial crisis, and COVID did not stop market growth.
Innovation remains and bubbles disappear.
The Nasdaq is a collection of the world's innovative companies.
QLD investors are investing in technological innovation.
Crashes are not exceptions but part of the market.

A Sentence to Remember

"The market does not grow because of crises. It grows because of humanity's ability to keep advancing even through crises."''',
    ),
    _BookChapter(
      title: 'Ch7. Lessons from the Dot-com Bubble',
      body: '''Even those who saw the future correctly could lose money.

The Belief That the Internet Would Change the World

In the late 1990s, the internet was the hottest topic in the world. Today we know how important the internet is. Online shopping, search engines, email, the cloud, artificial intelligence — the internet was at the starting point of all of it. So the people of that time were not wrong to believe in the internet's future. In fact, they were right. The problem was that seeing the future correctly and succeeding at investing are completely different matters.

An Era When Everyone Became a Genius

From 1998 to early 2000, the American stock market experienced a near-manic surge. Internet-related companies in particular exploded upward. No revenue, no profit, no clear business model was fine. If a company name had ".com" in it, investors flocked.

At the time, sayings like these were fashionable: "In the internet age, you can't evaluate company value the old way." "Growth potential matters more than revenue." "We can think about profit later." Looking back now it sounds dangerous, but at the time it was accepted as common sense. People became rich every day. Taxi drivers, college students, and office workers all talked about stocks. People who didn't invest seemed strange.

As a bull market extends, people mistake themselves for having become smart. In reality the market lifted them, but they believe it is their own skill. But most did not analyze companies. They simply bought because prices were rising. And historically, every time the phrase "this time is different" appeared, risk was growing.

How Does a Bubble Collapse?

In March 2000, the mood began to change. Investors slowly started seeing reality. Many internet companies still couldn't make money. Stock prices began to fall. At first no one cared. "It'll rise again soon." But the decline did not stop. And fear began.

In a bull market, greed is contagious. In a bear market, fear is contagious. Selling begets selling, fear begets fear. Eventually the Nasdaq index experienced a fall of nearly 80%. Many investors left the market.

The most important lesson from the dot-com bubble is this: the internet did not fail. The investors failed. This distinction is very important. The internet afterwards completely changed the world. Amazon became the world's largest e-commerce company. Google became the center of internet search. Netflix changed the entertainment industry. Innovation actually succeeded. But many investors did not experience that success. Because they gave up during the bubble's collapse.

Buffett's Perspective

Warren Buffett received much criticism during the dot-com bubble period. People thought Buffett was behind the times. Because he did not invest in internet companies. Buffett did not invest in businesses he could not understand. At the time, this decision looked foolish. But after the bubble collapsed, the situation completely changed. Buffett survived and continued to grow afterward. The reason he is special is that he did not abandon his principles even in the hottest market.

The Lesson for AI and QLD Investors

Many investors ask today: "Is the current AI boom the same as the dot-com bubble?" AI is a real innovation. There is no doubt about this. But investors must always remember. Innovation and investment returns are not the same concept. A good technology does not necessarily make a good investment. What matters is price. There is no need to doubt the innovation. But price must always be questioned.

The dot-com bubble is not simply a historical event. It is a case that every investor must repeatedly study. Because human psychology does not change. New bubbles will emerge in the future. And people will again say "this time is different." Buffett would recall the dot-com bubble at that moment and ask: "Am I investing in innovation? Or am I simply intoxicated by rising prices?"

Chapter 7 Summary
The internet revolution was real, but the bubble was also real.
Innovation and investment success are not the same meaning.
Price and value are different.
Bubbles start from herd psychology.
Warren Buffett kept his principles even in the hottest times.
Innovation remains and bubbles disappear.
The same principles apply in the AI era.
QLD investors must consider not only innovation but also price.

A Sentence to Remember

"Seeing the future correctly is not enough. You must invest at the right price."''',
    ),
    _BookChapter(
      title: 'Ch8. Lessons from the Financial Crisis',
      body: '''When the market seems to collapse, what should an investor do?

"This Time It Really Feels Like the End"

On September 15, 2008, the giant American investment bank Lehman Brothers filed for bankruptcy. People at the time could not believe it. A giant financial company with 158 years of history had collapsed overnight. The news delivered shocking reports day after day. Banks were shaking, real estate prices were collapsing, companies halted hiring. Unemployment surged and the stock market fell every day.

Investors around the world had the same thought: "This time it really feels like the end." Many people believed the capitalist system itself might collapse. Looking back now it might sound exaggerated. But to those who were there at the time, it was reality. Fear is always stronger than logic.

How Did the Financial Crisis Begin?

Interestingly, the financial crisis did not occur suddenly. The seeds of crisis were sown much earlier. The American real estate market had been rising for a long time. People began to believe house prices would never fall, and banks thought the same. They started lending even to people with poor credit. "House prices will keep rising anyway, so it's fine." This logic dominated the entire market.

At first there was no problem. House prices kept rising and everyone made money. But that was the problem. Because risk appeared to have disappeared. In reality, risk had not disappeared — it was merely hiding.

Most people think bear markets are dangerous. But historically, the most dangerous periods were often bull markets. In bull markets, vigilance disappears. People increase debt, take on more risk, remove safety measures, and rationalize by saying "what's the problem when the market keeps rising?" Exactly the same thing happened before the 2008 financial crisis.

Buffett's Action

During the 2008 financial crisis, most people were leaving the market. Fear was at its peak. But Warren Buffett did something different. He was looking for good companies. While many people were dumping stocks, he was looking for buying opportunities. The reason this was possible is simple. He trusted the value of companies over the market's emotions. And the crisis actually passed. The economy recovered and the market hit new highs. Buffett once again proved the power of principles.

Why Do People Make Mistakes in a Crash?

When a crash comes, people view the future pessimistically. When stocks fall, they seem like they'll fall further, and when news is bad, the situation seems like it will worsen. But the market reflects not the present but the future. The biggest problem is that the moment people view the future most pessimistically is often the moment of the greatest opportunity. Late 2008, March 2020 — historically, the greatest opportunities were mostly in the midst of fear. But at that moment, no one recognizes it as an opportunity.

How Should QLD Investors View the Financial Crisis?

QLD seeks approximately 2x the movement of the Nasdaq 100. Therefore, in a situation like a financial crisis, the decline can also appear much larger. But the real risk is not volatility. It is your own reaction to volatility. If an investor cannot endure the decline and sells at the bottom, that is the risk. Conversely, if you have cash prepared and execute a planned strategy, a crash can even become an opportunity. Starting fractional purchases at QLD -20%, adding at -30%, buying aggressively at -40%, reviewing long-term opportunities at -50% — what matters is not emotion but planning. What is needed in a crisis is not predictive ability but preparation.

The financial crisis is a history of human psychology. People forget risk in bull markets and forget hope in bear markets. And they repeat the same mistakes. Successful investors, on the other hand, stick to their principles. They maintain composure even in the midst of fear. Over time, that difference shows up as enormous results.

Chapter 8 Summary
The financial crisis was not a sudden event but the result of ignoring risk.
A bull market can actually be the most dangerous period.
The margin of safety is the core of investing.
Buffett found opportunity in the midst of fear.
Crashes test the investor's psychology.
Even with ETFs, crises do not disappear.
QLD investors must manage their own behavior rather than volatility.
Those who survive crises ultimately become the winners of compounding.

A Sentence to Remember

"Crises can break investors, but they can also make prepared investors wealthy."''',
    ),
    _BookChapter(
      title: 'Ch9. Lessons from the COVID Crash',
      body: '''When the world seemed to stop, the market was looking at the future.

A Crisis No One Anticipated

In early 2020, most investors thought it would be an ordinary year. The American economy was solid, unemployment was low, and corporate earnings were healthy. The Nasdaq was heading toward all-time highs. Then a small piece of news from Wuhan, China began to shake the world. At first, many people thought little of it. Epidemics had existed before. They thought it would soon be over.

But the situation deteriorated far faster than expected. Countries began closing borders. Cities were locked down. Schools closed. Factories stopped, planes disappeared, and people could not go outside. It was an unprecedented situation in modern economic history.

The Fastest Crash in History

From late February 2020, the market began to shake violently. And in March, fear turned into panic. The S&P 500 fell more than 30% in just a few weeks. The Nasdaq also plunged sharply. Leveraged ETFs like QLD swayed even more dramatically. Accounts shrank every day, and the news grew more gloomy. People endlessly asked the same questions: "Isn't this time really different?" "Hasn't the economy completely stopped?" "Should I sell all my stocks?"

What was clear was the difference from previous crises. The financial crisis was a financial system problem, and the dot-com bubble was a tech company bubble problem. But COVID stopped economic activity itself. Restaurants closed, airlines stopped, hotels emptied, and people could not consume. The engine of the economy seemed to have switched off.

Volatility inherently exists in the stock market. But the COVID crash was too fast. Most investors had no time to even adapt to the plunge. In this situation the human brain responds instinctively. "I have to flee." Fear overwhelms logic. Many investors could not endure the losses and left the market.

Why Did the Market Rebound?

To understand the COVID crash, you must understand the nature of the market. The market does not reflect the present. The market reflects the future. In March 2020, investors could make two choices. Looking only at the present — hospitals were overwhelmed, the economy stopped, people were anxious. Or looking at the future — eventually a vaccine would be developed, the economy would restart, people would consume again. The market ultimately chose the second. And surprisingly, the market began to recover before the economy.

Buffett always maintained the same philosophy. He believed the American economy would grow in the long term. He believed humanity would solve problems. The Great Depression, World War II, the financial crisis — all were overcome. COVID was also ultimately overcome. What Buffett trusted was not short-term news but humanity's capacity for adaptation.

The World Became Stronger After COVID

Interestingly, COVID made some companies even stronger. Remote work spread, the cloud industry grew, e-commerce expanded explosively, and AI technology investment accelerated. Microsoft and Amazon grew further, and Nvidia subsequently stood at the center of the AI revolution. Crisis always creates change. And change creates new opportunity.

The COVID crash left ETF investors with a very important lesson. The market can fall more than expected. But at the same time, it can also recover faster than expected. Most investors try to time the market recovery, but historically that has been nearly impossible. The best strategy has usually been simple. Hold good assets and endure. And if necessary, add purchases during the decline.

What COVID Taught QLD Investors

The COVID crash has special meaning for QLD investors. Because leveraged ETFs make fear feel even greater. When the Nasdaq falls, QLD shakes more. So investors are tested on their principles. Are you really a long-term investor? Do you really believe in technological innovation? Can you really stick to your plan? COVID posed these questions. And the market ultimately showed the answer. Long-term technological innovation did not stop. It actually accelerated.

Looking at history, every crisis has a common thread. During that period, it seems like it will never end. But it always ended. What matters is not the ability to predict crises. It is the ability to stick to principles even through crises. Long-term investors do not prophesy the future. Instead, they prepare so that they can survive no matter what future comes.

Chapter 9 Summary
The COVID crash was one of the fastest market collapses in modern history.
The market reflects the future rather than the present.
The value of quality companies and market prices can differ.
Buffett trusted humanity's capacity for adaptation.
Crises sometimes accelerate new innovation.
ETF investors need principles more than market timing.
QLD investors must look toward long-term technological innovation even through volatility.

A Sentence to Remember

"Even in the moments when the market looks darkest, the future is still being made."''',
    ),
    _BookChapter(
      title: 'Ch10. The AI Revolution and Today\'s Market',
      body: '''Are we standing at another historic inflection point?

People Have Always Underestimated the Future

In 1903, when the Wright brothers built an airplane, many people laughed. "A human flying through the sky?" It sounded like an unrealistic story. When personal computers appeared in the 1980s, it was similar. Most people thought computers would become equipment used only by some specialists. The internet in the 1990s was the same. Many people thought the internet was just a fad.

But history has repeatedly shown the same fact. Humans overestimate short-term change and underestimate long-term change. And now we stand before yet another massive change. It is artificial intelligence (AI).

Why Is AI Special?

Most past technological innovations helped human physical labor. Steam engines took over hard work, automobiles helped with transportation, computers helped with calculation, and the internet helped with information delivery. But AI is somewhat different. AI helps human intellectual labor. It writes text, translates, analyzes, writes code, creates images, and even assists in decision-making. This is not merely technological advancement. It may be the beginning of a productivity revolution.

The reason the stock market rises in the long run is ultimately productivity. When one person can create more value, corporate profits increase. When corporate profits increase, company value increases. And stock prices ultimately rise. The Industrial Revolution, electricity, computers, the internet — all raised productivity. AI is walking the same path. Therefore, long-term investors are not simply investing in AI companies — they are investing in a productivity revolution.

Is the AI Boom the Same as the Dot-com Bubble?

Many investors ask: "Isn't the current AI boom a dot-com bubble?" The answer is not simple. AI is a real innovation. Likewise, the internet was a real innovation. The problem is that technology and stock prices do not always move at the same speed. During the dot-com bubble, the internet was real, but the prices of some companies were unrealistic. Today's AI may have similar risks. Good technology does not necessarily mean good investment returns.

Buffett has always been cautious about new technology. He focused on businesses he could understand, and did not chase trends. He looked at companies' competitive advantages and ability to generate profits. He always asked the same questions: "Is this price reasonable?" "Isn't too much expectation already reflected?" "Does a margin of safety exist?" This is the core of Buffett's investment philosophy.

What Nvidia Symbolizes

When talking about the AI revolution of the 2020s, the first company that comes to mind is Nvidia. Until just a few years ago, Nvidia was strongly perceived as a gaming graphics card company. But as the AI era opened, the situation completely changed. Nvidia's GPUs became the core infrastructure of the AI industry. Companies around the world began purchasing Nvidia chips to develop AI models. What matters is not the stock price. It is the fact that AI has begun to actually influence economic activity.

ETF Investing and QLD in the AI Era

Most individual investors find it difficult to predict the ultimate winner of the AI industry. Accurately predicting which company will be strongest in 10 years is nearly impossible. That is why ETFs matter. ETFs allow participation in the growth of an entire industry rather than a specific company. The Nasdaq 100 includes many of the core companies of the AI revolution. Apple, Microsoft, Nvidia, Amazon, Meta, Broadcom — all have a high probability of benefiting from the AI revolution. ETF investors can participate in the flow of innovation without the burden of picking individual winners.

AI is a very important topic for QLD investors. Because QLD seeks approximately 2x the movement of the Nasdaq 100. The more the AI revolution succeeds, the more likely QLD is to benefit greatly. But at the same time, if expectations overheat, volatility can also increase. So long-term investors must remember two things simultaneously. First, AI is likely a real innovation. Second, the market can overheat in the short term.

Many investors try to predict how far AI will develop. But historically, the most successful investors were not people who accurately predicted the future. They were people who understood the direction of change. What matters is not tomorrow's stock price. It is thinking about how productivity will change over the next 10 to 20 years. The real value of AI is not new products. It is productivity improvement. Making it possible to do more work in less time. Looking back at human history, productivity revolutions have always driven economic growth. Long-term investors are people who invest in exactly that.

Chapter 10 Summary
AI is likely not just a trend but a productivity revolution.
The market reflects productivity improvement in the long run.
The lesson of the dot-com bubble is to distinguish innovation from price.
Nvidia is a representative case of the AI revolution.
Buffett looks at competitive advantage rather than trends.
ETFs can be an efficient way to participate in the AI revolution.
QLD investors must understand both the benefits and volatility of the AI revolution.

A Sentence to Remember

"A great investor is not someone who accurately predicts the future, but someone who steadily participates in the changes that are shaping the future."''',
    ),
  ];

  static const _japaneseBodies = <String>[
    // Ch1. 投資と投機の違い
    '''市場に参加した人は全員、投資家なのだろうか？
ドットコムバブルは、「インターネット」という言葉さえつければ株価が上がる時代だった。売上もなく、利益もなく、ビジネスモデルさえ不明確な企業が存在した。それでも投資家たちは熱狂した。株価は毎日上がった。メディアは新しい富豪の話を次々と報じた。大学生は教室よりも株式掲示板を見る時間のほうが長く、サラリーマンは昼休みのたびに銘柄の話をした。

当時、多くの人が自分を投資家だと思っていた。しかし私がその光景を見ていたなら、こう言っていただろう。「彼らは投資家ではない。」彼らは投機師だった。

2000年にバブルが崩壊すると、数多くの企業が消えた。一夜にして数十パーセントの損失が発生し、生涯かけて積み上げた資産を失った人も少なくない。興味深いのは、損失を出した人々のほとんどが、自分が何を買ったのか正確に説明できなかったという事実だ。彼らは企業を買ったのではなく、価格の上昇を買ったのだ。これこそが投資と投機の違いである。

投資と投機はまったく異なるゲームだ

ほとんどの人は投資と投機を似たようなものだと考えている。株を買えば投資で、コインを買えば投機だと考える人もいる。しかし私はまったく違う考え方をする。私はこの文章の中で、投資とは次の三つの条件を満たさなければならないと述べている。

第一に、十分な分析が必要である。第二に、元本保護が考慮されなければならない。第三に、満足できるリターンが期待できなければならない。この条件を満たさないものはすべて投機だと私は定義する。

重要なのは何を買うかではない。どんな考えで買うかが重要だ。アップルの株を買っても、理由が「明日上がりそうだから」なら投機だ。逆にETFを買っても、企業の成長性と長期的な経済発展を分析した結果であれば投資に近い。商品が投資と投機を分けるのではない。考え方が分けるのだ。

価格は毎日変わるが、価値はゆっくり変わる

株式市場に初めて入った人々は、ほとんどが価格に集中する。今日何パーセント上がったか、今週いくら儲かったか、他の人はどんな銘柄を買っているか。しかし投資家は価格よりも価値を見る。

例を挙げよう。あなたがソウルの江南に建物を一棟所有していると仮定しよう。ある日、誰かが来て50億ウォンで買うと言う。翌日は40億ウォンで買うと言う。そして一週間後、また55億ウォンで買うと言う。建物そのものは何も変わっていない。家賃も同じだ。立地も同じだ。建物の価値も大きく変わっていない。変わったのは提示価格だけだ。

株も同じだ。市場価格は毎日動く。しかし企業の価値はそれほど速く変わらない。投資家は価値を見る。投機師は価格だけを見る。

人間はもともと投機が好きだ

投資が難しい理由は人間の本能にある。人々はゆっくり金持ちになることを嫌う。年10%のリターンを20年間維持する話は退屈だ。しかし1ヶ月で300%上昇した銘柄の話は面白い。だから人々は自然に投機に引き寄せられる。

私たちの脳はもともと即座な報酬を好むように設計されている。今日1%を稼ぐよりも、明日100%を稼げる可能性に対してより興奮する。問題は市場がその心理を絶えず利用しているという点だ。

上昇相場では誰もが天才のように見える。どんな銘柄を買っても上がる。周囲の人々はお金を稼いでいる。SNSは利益報告で溢れかえる。その瞬間、投資家は知らず知らずのうちに考える。「自分だけ取り残されているのではないか？」まさにその瞬間から分析は消え、感情が投資の意思決定を支配し始める。

なぜウォーレン・バフェットは富を築いたのか

多くの人はウォーレン・バフェットが並外れた投資スキルを持っていると考えている。もちろん事実だ。しかし彼の最も強力な武器は銘柄選定能力ではない。時間だ。

バフェットは若い頃から良い企業を見つけ、長期間保有した。彼は翌日の株価を予測しようとしなかった。来月の金利を当てようとしなかった。来四半期の業績を予測しようともしなかった。彼はシンプルな問いに集中した。「この企業は10年後も強いだろうか？」「20年後も生き残っているだろうか？」この問いが彼の人生を変えた。実際、バフェットの資産のほとんどは60歳以降に築かれた。複利が機能する時間を十分に与えたからだ。投機師は時間を敵だと考える。投資家は時間を友にする。

現代の投資家にETFが重要な理由

私が初めて投資を学んだ頃は、ほとんどがファンドだった。しかし今日の個人投資家はずっと有利な環境にある。QQQ、SPY、VOO、そしてQLDのようなETFが存在する。これらの商品は数十、数百の企業に自動的に分散投資することを可能にしてくれる。

しかし一つだけ変わらないことがある。ETFも投資として使うことができるし、投機として使うこともできるという点だ。毎日価格だけを眺めているなら、ETFも投機のツールになる。逆に、長期的な経済成長に参加するという観点でアプローチすれば、優れた投資手段となる。

QLD投資家は何に投資しているのか

多くの人はQLDを単なるレバレッジETFだと考えている。しかしそれは半分しか正しくない。QLDはナスダック100指数の約2倍のリターンを追求する。つまり、QLDを保有するということは単にETFを保有することではなく、アメリカの技術革新に参加することだ。アップル、マイクロソフト、エヌビディア、アマゾン、メタ、ブロードコム——これらの企業が今後も成長すると信じるなら、QLDは投資対象になり得る。しかし単に「来月上がりそうだ」という理由でアプローチするなら、それは投機に過ぎない。同じ商品、異なる考え方。結果はまったく異なる。

投資家の最大の敵

初心者投資家は市場を恐れる。暴落を恐れる。経済危機を恐れる。しかし時間が経つと、本当の敵が誰なのかわかってくる。投資家の最大の敵は市場ではない。自分自身だ。恐怖、貪欲、焦り、後悔、嫉妬——これらの感情が数多くの投資家を市場の外へ追い出す。市場は最終的に回復することが多い。しかし恐怖に打ち負かされた投資家は回復しない。だから投資の本質は銘柄選択ではない。心理管理だ。

第1章 まとめ
投資と投機はまったく異なる。
投資家は価値を買い、投機師は価格を買う。
価格は毎日変わるが、価値はゆっくり変わる。
人間の本性は投機を好む。
バフェットの最大の武器は予測ではなく時間だった。
ETFも投資手段になり得るし、投機手段にもなり得る。
QLDはアメリカの技術革新への長期投資の観点でアプローチすべきだ。
投資家の最大の敵は市場ではなく自分の感情だ。

覚えておくべき言葉

「投資は未来を当てるゲームではない。良い資産を適切な価格で買い、十分な時間を与えるプロセスだ。」''',
    // Ch2. なぜほとんどの投資家は失敗するのか
    '''市場は難しくない。しかし人間の感情は難しい。
最も危険なのは無知ではない

多くの人は、投資に失敗する理由は情報不足だと考えている。良い銘柄を知らないから、経済を知らないから、専門家ではないから。だから投資に成功するには膨大な知識が必要だと信じる。もちろん知識は重要だ。しかし投資の歴史を振り返ると、驚くべき事実が見えてくる。ほとんどの投資家は知らないことで失敗するのではない。知っていても失敗するのだ。

人々は「安く買って高く売るべきだ」という事実を知っている。長期投資が重要だという事実も知っている。恐怖で売ってはいけないという事実も知っている。しかし実際の状況になると、まったく反対の行動をとる。株価が上がるときはもっと上がりそうだから買い、株価が下がるときはもっと下がりそうだから売る。結果として高く買って安く売る。問題は情報ではない。問題は行動だ。そして行動を決めるのは感情だ。

人間の脳は投資に不利なように設計されている

人間はもともと投資家になるように進化したのではない。数十万年の間、人間は生存のために即座な危険に反応しなければならなかった。森の中で猛獣が現れたら逃げなければならなかった。火が起きたら避けなければならなかった。危険を過大に認識することが生存に有利だった。

しかし金融市場は違う。市場の下落は猛獣ではない。株価が20%下落しても、明日すぐに굶え死にするわけではない。しかし人間の脳はそう受け取らない。株式口座が赤く染まり始めると、脳は実際の危険と似たレベルのストレスを感じる。だから恐怖に陥る。そして恐怖は合理的な判断を麻痺させる。これが多くの投資家が暴落時に売却する理由だ。

ドットコムバブルが残した教訓

1990年代後半のアメリカではインターネット革命が始まっていた。新しい技術が登場し、世界は急速に変わっていた。人々はインターネットが未来だと信じた。その信念自体は間違っていなかった。実際、インターネットは世界を変えた。問題は人々が未来を信じたのではなく、価格に酔いしれたという点だ。

当時は企業名に「.com」がついただけで株価が急騰した。売上がなくても、利益がなくても、ビジネスモデルがなくても構わなかった。人々は「どうせ上がり続けるだろう」と考えた。しかし現実は違った。2000年にバブルが崩壊し始めた。数多くのインターネット企業が消えた。ナスダック指数は約80%近くも暴落した。当時市場に初めて参入した多くの個人投資家が大きな損失を被った。興味深いのは、彼らがバカではなかったという事実だ。むしろ賢い人も多かった。しかし群集心理に勝てなかった。人々が稼いでいる姿を見て遅れて飛び込んだ。そして結果として最も高い価格で買った。

金融危機はまた別の姿を見せた

2008年の金融危機はドットコムバブルとは反対だった。今度は貪欲ではなく恐怖が市場を支配した。ニュースでは毎日経済崩壊を語っていた。大手金融機関が倒産した。失業率は急上昇した。人々は現金を持っていなければ安全でないと考えた。当時多くの投資家が「今回は本当に違う」と言った。しかし歴史的に市場は常に似た言葉を聞いてきた。1929年にも、1973年にも、1987年にも、2000年にも、そして2008年にも。恐怖はいつも特別に見える。しかしほとんどの場合、市場は結局回復した。問題は多くの投資家が回復を待てなかったことだ。彼らは最悪のタイミングで売却した。そして回復が始まった後、また高い価格で戻ってきた。

コロナ暴落は人間の心理を改めて証明した

2020年のコロナパンデミックはまた一つの実験だった。わずか数週間で市場は急落した。都市が封鎖され、工場が止まり、飛行機が止まり、経済活動が停止した。当時多くの専門家が長期の不況を予想した。しかし市場は予想よりもはるかに早く回復した。恐怖で売却した人々は衝撃を受けた。彼らが市場の外で待っている間に市場は再び上昇し始めた。一方、原則を守った投資家は回復の恩恵を受けた。コロナ暴落は重要な事実を改めて示した。投資の成功は未来を当てる能力ではなく、原則を守る能力だという事実だ。

私の警告

私は投資家の最大の敵が自分自身である可能性があると考える。多くの人は市場に勝とうとする。しかし実際には自分の感情に勝つことのほうがずっと難しい。市場は強制的に売らせることはしない。決断を下すのは結局投資家自身だ。したがって投資家は市場よりも自分の心理をまず理解しなければならない。恐怖に陥ったときにどんな行動をとるか、貪欲を感じたときにどんなミスを犯すか——自分の弱点を知らなければならない。

バフェットが特別な理由

バフェットは自分が未来を正確に予測できないことをよく知っている。だから彼は予測よりも原則に頼る。良い企業、強い競争力、健全な財務構造、合理的な価格。彼は数十年間同じ原則を繰り返した。市場が恐怖に陥っても原則を捨てなかった。彼の強みは知能よりも一貫性にあった。

ETF投資家も同じミスを繰り返す

多くの人はETFを買えば自動的に成功すると考える。しかしETFも結局人間が投資する。ETF投資家も恐怖に陥ることができる。実際に多くの投資家がETFを最も高い時期に買い、最も安い時期に売る。ETFは良いツールだ。しかしツールがユーザーの感情を取り除いてくれるわけではない。長期投資に成功するためにはETFより重要なものがある。それは行動だ。

QLD投資家が必ず知っておくべきこと

QLDは一般的なETFよりもボラティリティが大きい。上昇するときは速く上昇するが、下落するときも速く下落する。したがって感情に従って行動する投資家は長期的に生き残ることが難しい。QLD投資家は下落を例外ではなくプロセスとして受け入れなければならない。-20%も、-30%も、-40%も、場合によってはそれ以上もあり得る。重要なのは下落ではなく対応だ。あらかじめ原則を決めておいた投資家は揺れない。しかし原則のない投資家は市場とともに揺れる。

第2章 まとめ
ほとんどの投資家は情報不足よりも感情のために失敗する。
人間の脳はもともと投資に不利なように設計されている。
ドットコムバブルは貪欲の危険性を示す。
金融危機とコロナ暴落は恐怖の危険性を示す。
私は投資家の最大の敵が自分自身だと言う。
バフェットの強みは予測能力ではなく原則を守る能力だった。
ETF投資家も感情をコントロールできなければ失敗することがある。
QLD投資家はボラティリティを受け入れ、計画に従って行動すべきだ。

覚えておくべき言葉

「市場はあなたを破滅させない。恐怖と貪欲に揺れるあなたの行動があなたを破滅させる。」''',
    // Ch3. 市場
    '''市場はあなたの主人ではなく、下僕だ
毎朝ドアをノックする不思議な男

想像してみよう。あなたがある優れたビジネスの共同オーナーだと仮定しよう。ビジネスは安定的に成長している。毎年売上が増え、収益も着実に伸びている。しかし一つ不思議なことがある。毎朝一人の男があなたの家のドアをノックする。その男の名前は市場だ。

彼は毎日同じ質問をする。「今日、あなたの持ち分を買います。」または「今日、私の持ち分を買いますか？」問題は彼が提示する価格が毎日変わるということだ。ある日は非常に楽観的だ。ビジネスの見通しが明るいとして法外に高い価格を提示する。一方、ある日はまったく落ち込んで、安値で売ろうとする。ビジネス自体は何も変わっていないのに価格だけが大きく変わるのだ。

私はまさにこの比喩を通じて株式市場の本質を説明する。私はこの不思議な男を「市場氏(Mr. Market)」と呼ぶ。

ほとんどの人は市場を誤解している

私にとって市場は単なるツールだ。しかしほとんどの人は彼を師匠のように扱う。市場価格が上がると喜び、市場価格が下がると不安になる。まるで市場が真実を知っているかのように行動する。しかし市場は予言者ではない。市場はただ価格を提示するだけだ。その価格が必ずしも正しいわけではない。むしろ歴史的に市場は数え切れないほど間違ってきた。

ドットコムバブル時代の市場

1999年、市場は世界で最も楽観的な人物になった。インターネットが世界を変えるという信念は事実だった。問題はその信念が狂気に変わったことだ。売上もなく利益もない企業が数十億ドルの価値を認められた。企業名に「.com」がついただけで株価が急騰した。当時市場は毎日より高い価格を叫び、人々は「市場がこれだけ評価しているのだから間違いのはずがない」と考えた。しかし市場は間違っていた。2000年にバブルが崩壊すると数多くの企業が消えた。当時の価格は企業価値ではなく集団的な興奮を反映した数字に過ぎなかった。

金融危機時代の市場

2008年になると状況は一変した。今度は貪欲ではなく恐怖が市場を支配した。市場は毎日より低い価格を提示した。多くの投資家は市場が何かを知っていると思い急いで売却した。しかし実際にはそうではなかった。優良企業は依然として製品を売っていた。従業員は依然として出勤していた。変わったのは人々の感情だけだった。数年後、市場は回復し新たな最高値を記録した。結局間違っていたのは企業ではなく市場の感情だった。

コロナ暴落は何を示したか

2020年のコロナパンデミックは市場のまた別の姿を見せた。わずか数週間で市場は急落した。ニュースは毎日最悪のシナリオを語り、人々は現金を持って逃げ出した。その瞬間市場は完全に恐怖に陥っていた。しかしわずか数ヶ月後に市場は反発し始め、1年後には史上最高値を更新した。興味深いのは企業の本質的な価値がそれほど速く変わったのではないという事実だ。変わったのは人々の感情だった。市場はその感情を価格として表現しただけだ。

バフェットはなぜ市場が好きだったのか

ウォーレン・バフェットは市場がとても好きだった。しかしほとんどの投資家とは理由が違った。人々は市場が上がると喜び下がると嫌がる。バフェットはむしろ市場が非合理的であるほど喜んだ。なぜなら機会が生まれるからだ。良い企業が恐怖のために安く取引されているなら、それは長期投資家への贈り物のようなものだ。バフェットは常に価格と価値を区別した。市場が低い価格を提示しても価値が低くなるわけではないと考えた。彼は市場を参考にはしたが、決して従うことはなかった。

QLD投資家にとって市場はさらに重要だ

QLDはナスダック100の約2倍の動きを追求する。したがって市場の感情がより極端に反映される。ナスダックが10%下落すれば、QLDははるかに大きく下落することがある。その瞬間多くの投資家は「これは間違っているのではないか？」「もっと下がるのではないか？」「今からでも売るべきか？」という考えをする。しかしこのときこそ市場の本質を理解しなければならない。価格は感情だ。価値は別の問題だ。もしアメリカのテクノロジー企業の長期的な競争力が維持されているなら、価格の下落が即座に価値の下落を意味するわけではない。むしろ長期投資家にとってはより良い参入機会になることもある。

賢明な投資家は市場を利用する

ほとんどの人は市場に利用される。市場が興奮すると一緒に興奮し、市場が恐怖に陥ると一緒に恐怖に陥る。しかし私は違う行動をする。市場が過熱すると警戒し、市場が恐怖に陥ると機会を探す。私は市場の気分についていかない。市場の気分を活用する。これこそが私の言う市場の真の意味だ。

第3章 まとめ
市場は毎日価格を提示するが、常に正しいわけではない。
価格と価値は異なる。
ドットコムバブルは市場の貪欲を示す。
金融危機とコロナ暴落は市場の恐怖を示す。
バフェットは市場の感情を利用した。
ETF投資家も市場心理に振り回されることがある。
QLD投資家は価格よりも価値に集中すべきだ。
市場は主人ではなく下僕だ。

覚えておくべき言葉

「市場はあなたに価格を提示するだけだ。その価格を受け入れるかどうかはあなたの選択だ。」''',
    // Ch4. 安全マージン
    '''偉大な投資家がまず考えたのは収益ではなく生存だった
飛行機に予備燃料がある理由

あなたが飛行機でソウルからニューヨークへ行くと仮定しよう。パイロットは出発前に燃料を計算する。ソウルからニューヨークまで必要な燃料を正確に計算することは難しくない。それでも航空会社はちょうど必要なだけの燃料しか積まない、ということはしない。常に余裕分を準備する。天候が悪化することもあるし、空港が混雑することもあるし、予期しない問題が発生することもあるからだ。もし必要な分だけの燃料しか積んでいなければ、たった一つの変数だけで致命的な結果が生じることがある。

投資も同じだ。問題はほとんどの投資家が利回りには執着しながら安全余裕には関心がないということだ。彼らはより高いリターンを求め、より速い富を求める。そしてその過程で最も重要なことを忘れる。それは生存だ。

私が最も重要だと考える概念

この文章を読んでいる人なら必ず覚えておくべき言葉がある。それは安全マージン(Margin of Safety)だ。私は数多くの投資原則を語るが、結局すべての哲学は安全マージンに帰結する。私は人間が未来を正確に予測することはできないと考える。経済の見通しも、企業業績の予測も、専門家の分析も、さらには自分の判断も間違いうる。だから私は常に問いかける。「私が間違えても生き残ることができるか？」この問いこそが安全マージンの始まりだ。

なぜほとんどの投資家は安全マージンを無視するのか

理由は単純だ。安全マージンは退屈だからだ。現金を保有すると利回りが低く見える。分散投資をすると大当たりが難しくなりそうだ。レバレッジを減らすと成長速度が遅くなりそうだ。人々は即座な結果を求めるため、リスクを過小評価する。

上昇相場では特にそうだ。市場が上がり続けるときは誰もが天才のように見える。保守的な投資家は出遅れているように見え、現金を持っている人はバカのように見える。しかし市場は常に同じ方法で人々を欺く。上昇相場ではリスクが見えない。下落相場が来て初めてリスクが見える。そしてそのときにはすでに手遅れの場合が多い。

バフェットが絶対にしないこと

ウォーレン・バフェットは世界最高の投資家の一人だが、意外にもしないことが多い。彼は理解できないビジネスには投資しない。過度な負債を嫌う。全財産を一つのアイデアに賭けない。バフェットが臆病者だからではない。彼はリスクを正確に理解しているからだ。

バフェットはこう言った。「ルール1：お金を失うな。ルール2：ルール1を忘れるな。」もちろん投資では損失が発生することもある。バフェットの言う本当の意味は、回復不可能な損失を避けよということだ。50%の損失が発生したら、元本を回復するには100%の上昇が必要だ。80%の損失なら400%の上昇が必要だ。95%の損失なら回復はほぼ不可能だ。だから偉大な投資家たちは利回りよりも生存を先に考える。

ドットコムバブルと金融危機が教えてくれたこと

1999年には安全マージンという概念自体が無視された。利益もない企業が数十億ドルの価値を認められ、人々は「今回は違う」と言った。歴史上最も危険な言葉の一つだ。2000年にバブルが崩壊すると数多くの企業が消えた。問題はインターネットではなかった。問題は安全マージンがなかったことだ。

2008年の金融危機も同じ教訓を残した。当時多くの金融機関が過大なレバレッジを使った。安全余裕がなかった。市場が少し揺れただけで崩れる構造だったため、結局崩れた。一方、十分な現金を保有していた企業は生き残った。さらに危機を機会として活用することもあった。危機はいつも安全マージンの重要性を証明する。

QLD投資家に安全マージンが重要な理由

QLDはナスダック100の約2倍のリターンを追求する。長期的に高い成長可能性があるが、ボラティリティも大きい。だから安全マージンがさらに重要だ。もしすべての資産をQLDに投資していれば、ナスダックが大幅に下落した場合、極度の心理的プレッシャーを受けることになる。多くの人がその瞬間に計画を諦める。逆に現金を保有していれば話が違う。下落は危機ではなく機会になる。

例えばQLD -20%で少額買い付け、-30%で現金の一部を投入、-40%で積極的な買い付け、-50%で長期的な観点の機会検討——このような戦略は結局安全マージンから出発する。現金は単なる待機資金ではない。機会を買える権利だ。

本当のリスクとは何か

多くの投資家はボラティリティをリスクだと考える。しかし私は違う考え方をする。本当のリスクは価格変動ではない。永続的な資本損失だ。株価が一時的に30%下落することはリスクではないかもしれない。しかし恐怖のために底値で売ること、良い企業を理解せずに投資すること、過大なレバレッジを使うこと——これが本当のリスクだ。安全マージンのない状態で投資することが本当のリスクだ。

第4章 まとめ
安全マージンは私の哲学の核心だ。
未来は予測できないため、常に余裕を持つべきだ。
利回りよりも生存が重要だ。
バフェットはリスクよりも生存確率を先に見る。
ドットコムバブルと金融危機は安全マージンの重要性を示す。
現金は機会を買える権利だ。
ETF投資家にも安全マージンが必要だ。
QLD投資家は特に現金とルールに基づく戦略が重要だ。

覚えておくべき言葉

「優れた投資家は最も多くの金を稼ぐ人ではない。最も長く生き残って複利の力を享受する人だ。」''',
    // Ch5. 群集心理と投資
    '''市場は数字で動くように見えるが、結局は人間の感情で動く
人々はなぜ同じミスを繰り返すのか

1637年のオランダで、チューリップの球根一つが家一軒分の価格で取引された。1929年のアメリカで、人々は借金をして株を買った。2000年のドットコムバブルで、収益のないインターネット企業が数十億ドルの価値を認められた。2021年のミーム株ブームで、業績とは関係なくインターネットコミュニティの熱狂によって株価が急騰した。

時代も異なり国も異なる。投資対象も異なる。しかし驚くほど共通点がある。人々はいつも同じミスを繰り返す。なぜだろうか？その理由は、市場は数字で動くように見えるが実際には人間の感情で動くからだ。恐怖、貪欲、希望、後悔、嫉妬——こうした感情が集まって価格を作る。そして投資家は思っている以上に感情に弱い。

人間はもともと群れに従うように進化した

数万年前、人類にとって群れに従うことは生存戦略だった。部族全体が一方向へ逃げるときに一人で残るのは危険だった。だから人間の脳は本能的に多数の行動を信頼するように発達した。

問題は金融市場がこの本能を利用するという点だ。市場で全員が同じ方向に動くとき、人々は強い心理的プレッシャーを感じる。周囲の人々が稼いでいると不安になり、SNSで利益報告が溢れると焦り、ニュースで新しい投資ブームを語ると取り残される感じがする。この感情を投資の世界ではFOMO（Fear Of Missing Out）、機会を逃しそうな恐れと呼ぶ。興味深いのは投資失敗の多くがこの感情から始まるという事実だ。

ドットコムバブルが示した群集心理の力

1999年のアメリカではインターネットが世界を変えるという信念が広がっていた。実はこの信念自体は間違っていなかった。インターネットは実際に世界を変えた。問題は人々が未来の可能性を現実よりもはるかに大きく評価したという点だ。インターネット企業なら無条件に上がると信じた。企業名に「.com」がつくだけで投資家が殺到した。人々は企業を分析しなかった。ただ他の人が買っているから従って買った。

群衆はお互いを説得した。「今回は違う。」「新しい時代が来た。」「昔の基準では説明できない。」そしていつもそうであるように市場は現実に戻ってきた。バブルは崩壊し、数多くの企業が消え、多くの投資家が財産の大部分を失った。群集心理は上昇相場で最も危険だ。なぜならその瞬間、全員が自分が正しいと信じているからだ。

金融危機は恐怖の群集心理を示した

ドットコムバブルが貪欲の事例なら、2008年の金融危機は恐怖の事例だった。当時人々は経済システム自体が崩壊すると考えた。ニュースでは毎日危機のニュースを伝えた。銀行が倒産し、失業率が上昇し、株価は下がり続けた。多くの投資家が恐怖に駆られて最も悪いタイミングで売却した。

上昇相場では群衆が貪欲であり、下落相場では群衆が恐怖的だ。しかし結果は似ている。どちらも誤った判断を生む。貪欲は過度に高い価格で買わせ、恐怖は過度に安い価格で売らせる。

私のアドバイス

私は市場の感情を理解することが重要だと言う。しかしより重要なのは感情に従わないことだ。私は投資家が群衆の意見を基準に判断してはならないと考える。ほとんどの人が買うからといって良い投資でもなく、ほとんどの人が売るからといって悪い投資でもない。重要なのは価値だ。市場参加者の数ではない。私は独立した思考を強調する。投資家は自ら判断しなければならない。群衆ではなく事実に基づかなければならない。

バフェットはなぜ反対の行動をしたのか

バフェットが特別な理由の一つは群衆と反対の行動ができたことだ。彼は市場が過熱したとき興奮しなかった。逆に市場が恐怖に陥ったとき機会を探した。2008年の金融危機当時、多くの投資家が市場を去るときバフェットは積極的に投資した。彼は他の人々の感情ではなく企業の価値を見た。恐怖が極度に高まる時期に買い付けることは人間の本能に反する行動だ。しかし長期投資家は本能よりも原則に従わなければならない。バフェットはそれを生涯実践した。

QLD投資家が必ず理解すべき心理

QLDは一般的なETFよりもボラティリティがはるかに大きい。したがって群集心理の影響をより強く受ける。QLDが急騰すると「今買わなければ遅れる」「今回は上がり続ける」という考えが浮かぶ。逆にQLDが急落すると「もっと下がりそうだ」「今からでも売るべきか」という恐怖が訪れる。しかしこのような感情は過去にも数えきれないほど繰り返され、これからも繰り返されるだろう。長期投資家は感情をなくそうとするのではない。代わりに感情に従って行動しない方法を学ぶ。それが核心だ。

感情ではなくルールで投資せよ

群集心理を完全になくすことはできない。人間だからだ。しかし影響を減らすことはできる。最良の方法はルールを作ることだ。QLD -20%で少額買い付け、-30%で現金の一部を投入、-40%で積極的な買い付け、-50%で計画された比率の投資——このようなルールがあれば感情が介入する余地が減る。市場が恐怖に陥っても行動基準が明確だ。ルールは感情の敵だ。そして長期投資家の最も強力な武器でもある。

第5章 まとめ
人間は本能的に群れに従うように設計されている。
投資失敗の多くは群集心理から始まる。
ドットコムバブルは貪欲の危険性を示す。
金融危機は恐怖の危険性を示す。
私は独立した思考を強調する。
バフェットは群衆と反対の行動ができた。
ETF投資家も群集心理に振り回されることがある。
QLD投資家はルールに基づく投資が特に重要だ。

覚えておくべき言葉

「群衆が確信に満ちているときに最も注意せよ。そして群衆が絶望に陥っているときに最も冷静であれ。」''',
    // Ch6. 市場はなぜ長期的に上昇するのか
    '''暴落は繰り返されるが、なぜ市場は最高値を更新し続けるのか
「今回は本当に終わったようだ」

投資人生の中で一度は、こんな考えが頭をよぎる。株式市場が暴落する。ニュースでは危機を語り、専門家たちは景気後退を警告し、人々は現金を持って逃げ出す。そして多くの投資家が同じ言葉を口にする。「今回は本当に終わったようだ。」

興味深い事実は、この言葉がほぼすべての時代に繰り返されてきたということだ。1929年の大恐慌、1973年のオイルショック、1987年のブラックマンデー、2000年のドットコムバブル、2008年の金融危機、2020年のコロナ暴落——毎回人々は世界が終わるかのように語った。しかし市場は結局回復した。そしてより高い場所へ上昇した。なぜだろうか？

市場は単なる数字ではない

多くの人は株式市場をチャートでしか見ない。しかし市場はチャートではない。市場は経済そのものだ。より正確に言えば、数多くの企業の集合体だ。アップル、マイクロソフト、エヌビディア、アマゾン、メタ、グーグル——これらの企業が毎日新しい製品を作り、サービスを改善し、顧客を増やしている。株価はその結果を反映する数字に過ぎない。したがって市場が長期的に上昇するということは、結局企業が成長しているということを意味する。企業が成長する限り、市場も成長する。

人類は絶えず発展してきた

100年前を考えてみよう。当時の人々はスマートフォンが何なのか知らなかった。インターネットもなかった。GPSもなかった。人工知能はSFにしか登場しなかった。しかし今私たちは手のひらの中のデバイスで全世界とつながり、数秒で情報を検索し、家から物を注文し、AIに質問をする。人類は絶えず生産性を高めてきた。そして生産性の向上は結局企業利益の増加につながった。企業利益が増加すれば株価も長期的に上昇する。市場上昇の最も根本的な原因はまさに生産性革新だ。

歴史を見れば常に革新があった。1800年代には鉄道が、1900年代には自動車が世界を変えた。電気は産業構造を変え、コンピューターは業務の仕方を変え、インターネットは情報の流れを変え、スマートフォンは生活様式を変えた。そして今AIが登場しつつある。もちろんすべての企業が生き残るわけではない。しかし経済全体は発展する。市場はその発展の果実を反映する。

危機の中でも市場は成長した

1929年のアメリカ大恐慌は歴史上最も深刻な経済危機の一つだった。失業率は20%を超え、銀行が崩壊し、数多くの人々が仕事を失った。当時の人々は資本主義自体が終わったと考えた。しかし資本主義は終わらなかった。企業は生き残るために変化し、新しい産業が登場し、経済は回復した。

多くの人はドットコムバブルを失敗として記憶する。しかしインターネットは失敗したのだろうか？いや。インターネットは人類の歴史上最も強力な革新の一つになった。失敗したのはインターネットではなかった。過大な期待だった。バブルは崩壊することがあるが、革新は残る。

2008年の金融危機のとき、人々はアメリカ経済が崩壊すると考えた。しかし危機はむしろ企業をより強くした。コスト構造を改善し、効率を高め、新しい技術を導入した結果、生き残った企業は以前より強くなった。市場は危機を通じて浄化されることもある。

ナスダックが特別な理由

QLD投資家なら必ず理解すべき部分だ。ナスダックは単なる株価指数ではない。世界で最も革新的な企業が集まる場所だ。アップル、マイクロソフト、エヌビディア、アマゾン、メタ、ブロードコム——これらの企業の共通点は未来を作るという点だ。技術革新の中心にあるという点だ。したがってナスダックは人類の生産性向上の直接的な恩恵を受ける。

QLDを保有するということは単にETFを保有することではない。人類の発展を信じることだ。技術革新を信じることだ。もちろん途中には暴落も来るし、バブルも来るし、恐怖も来る。しかし長期投資家はそのすべてを含めて投資する。暴落がないと信じるのではない。暴落があっても結局革新は続くと信じる。

市場は直線的に上がらない。階段のように上がる。上昇、調整、暴落、回復、そして再び上昇——このプロセスが繰り返される。多くの投資家は暴落を異常だと考える。しかし歴史的に暴落は正常だ。むしろ暴落のない市場が異常だ。したがって長期投資家は暴落をなくそうとするのではない。暴落を含めた状態で投資計画を立てる。

第6章 まとめ
市場は企業成長の結果を反映する。
長期的な市場上昇の原因は生産性の向上だ。
鉄道、自動車、インターネット、AIはすべて市場成長の原動力だった。
大恐慌、金融危機、コロナも市場の上昇を止めることができなかった。
革新は残り、バブルは消える。
ナスダックは世界の革新企業の集合体だ。
QLD投資家は技術革新に投資しているのだ。
暴落は例外ではなく市場の一部だ。

覚えておくべき言葉

「市場は危機のために成長するのではなく、危機の中でも発展し続ける人間の能力のために成長する。」''',
    // Ch7. ドットコムバブルの教訓
    '''未来を正しく見た人でもお金を失う可能性がある
インターネットが世界を変えるという信念

1990年代後半、インターネットは世界で最も熱い話題だった。今日私たちはインターネットがどれほど重要かを知っている。オンラインショッピング、検索エンジン、メール、クラウド、人工知能——すべての出発点にインターネットがあった。したがって当時の人々がインターネットの未来を信じたことは間違いではなかった。むしろ彼らは正しかった。問題は未来を正しく見ることと投資に成功することはまったく別の問題だということだった。

全員が天才になった時代

1998年から2000年初頭にかけてアメリカの株式市場は狂乱に近い上昇を経験した。特にインターネット関連企業は爆発的に上昇した。売上がなくても、利益がなくても、ビジネスモデルが不明確でも構わなかった。企業名に「.com」がついているだけで投資家が殺到した。

当時はこんな言葉が流行した。「インターネット時代には昔の方式で企業価値を評価することはできない。」「売上よりも成長性が重要だ。」「利益は後で考えればよい。」今見ると危険な話のように聞こえるが当時は常識として受け入れられた。人々は毎日金持ちになっていた。タクシー運転手も大学生もサラリーマンも株の話をした。株をやっていない人のほうがおかしく見えるほどだった。

上昇相場が長引くほど人々は自分が賢くなったと錯覚する。実際には市場が上げてくれたものなのに、自分の実力だと信じる。しかしほとんどは企業を分析しなかった。ただ価格が上がっていたから買った。そして歴史的に「今回は違う」という言葉が出るたびにリスクは高まった。

バブルはどのように崩壊するか

2000年3月、雰囲気が変わり始めた。投資家たちは少しずつ現実を見始めた。多くのインターネット企業がまだ収益を上げていなかった。株価が下落し始めた。最初は誰も気にしなかった。「すぐまた上がるだろう。」しかし下落は止まらなかった。そして恐怖が始まった。

上昇相場では貪欲が伝染する。下落相場では恐怖が伝染する。売りが売りを呼び、恐怖が恐怖を呼ぶ。結局ナスダック指数は約80%近くの下落を経験した。多くの投資家が市場を去った。

ドットコムバブルから最も重要な教訓はこれだ。インターネットは失敗しなかった。投資家が失敗したのだ。この違いは非常に重要だ。インターネットはその後世界を完全に変えた。アマゾンは世界最大の電子商取引企業になった。グーグルはインターネット検索の中心になった。ネットフリックスはエンターテインメント産業を変えた。革新は実際に成功した。しかし多くの投資家はその成功を経験できなかった。なぜならバブルが崩壊する過程で諦めたからだ。

バフェットの視点

ウォーレン・バフェットはドットコムバブルの時期に多くの批判を受けた。人々はバフェットが時代遅れだと考えた。インターネット企業に投資しなかったからだ。バフェットは自分が理解できないビジネスには投資しなかった。当時はこの決断がバカのように見えた。しかしバブルが崩壊した後、状況は一変した。バフェットは生き残り、その後も成長し続けた。彼が特別なのは最も熱い市場でも原則を諦めなかったからだ。

AIブームとQLD投資家の教訓

今日多くの投資家が問う。「今のAIブームはドットコムバブルと同じだろうか？」AIは実際の革新だ。この点は疑う余地がない。しかし投資家は常に覚えておかなければならない。革新と投資収益は同じ概念ではない。良い技術だからといって必ず良い投資になるわけではない。重要なのは価格だ。革新を疑う必要はない。しかし価格は常に疑うべきだ。

ドットコムバブルは単なる歴史的な出来事ではない。すべての投資家が繰り返し学ぶべき事例だ。なぜなら人間の心理は変わらないからだ。これからも新しいバブルが登場するだろう。そして人々はまた「今回は違う」と言うだろう。バフェットならその瞬間ドットコムバブルを思い浮かべてこう問うただろう。「今革新に投資しているのか？それとも単に価格上昇に酔いしれているのか？」

第7章 まとめ
インターネット革命は現実だったが、バブルも現実だった。
革新と投資の成功は同じ意味ではない。
価格と価値は異なる。
バブルは群集心理から始まる。
バフェットは最も熱い時期でも原則を守った。
革新は残り、バブルは消える。
AI時代にも同じ原則が適用される。
QLD投資家は革新だけでなく価格も考慮すべきだ。

覚えておくべき言葉

「未来を正しく見るだけでは十分ではない。正しい価格で投資しなければならない。」''',
    // Ch8. 金融危機の教訓
    '''市場が崩壊するように見えるとき、投資家は何をすべきか
「今回は本当に終わった」

2008年9月15日、アメリカの巨大投資銀行リーマン・ブラザーズが破産を申請した。当時人々は信じられなかった。158年の歴史を持つ巨大な金融会社が一夜にして崩壊したのだ。ニュースは毎日衝撃的な話を伝えた。銀行が揺れ、不動産価格が暴落し、企業は採用を中断した。失業者は急増し、株式市場は毎日暴落した。

世界中の投資家が同じ考えをした。「今回は本当に終わったようだ。」多くの人々は資本主義システム自体が崩壊する可能性があると信じた。今振り返ると誇張した考えのように聞こえるかもしれない。しかし当時現場にいた人々にとっては現実だった。恐怖はいつも論理より強い。

金融危機はどのように始まったのか

興味深いことに、金融危機は突然発生したのではなかった。危機の種はそれよりずっと以前に蒔かれていた。アメリカの不動産市場は長い間上昇していた。人々は住宅価格が絶対に下がらないと信じ始め、銀行もそう考えた。信用力の乏しい人々にも貸し付けを始めた。「どうせ住宅価格が上がるから大丈夫だ。」この論理が市場全体を支配した。

最初は問題がなかった。住宅価格は上がり続け、全員がお金を稼いでいた。しかしそれが問題だった。リスクが消えたように見えたからだ。実はリスクは消えたのではなく隠れていただけだった。

ほとんどの人は下落相場を危険だと考える。しかし歴史的に最も危険な時期はむしろ上昇相場の場合が多かった。上昇相場では警戒心が消える。人々は借金を増やし、より多くのリスクを負い、安全装置を外しながら「市場が上がり続けているのに何が問題だ？」と合理化する。2008年の金融危機以前にもまったく同じことが起きていた。

バフェットの行動

2008年の金融危機当時、ほとんどの人々が市場を去っていた。恐怖が極限に達していた。しかしウォーレン・バフェットは違う行動をとった。彼は良い企業を探していた。多くの人々が株を投げるときに彼は買い付けの機会を探していた。これが可能な理由は単純だ。彼は市場の感情よりも企業の価値を信じていたからだ。そして実際に危機は過ぎ去った。経済は回復し、市場は新たな最高値を記録した。バフェットはまたも原則の力を証明した。

下落相場で人々はなぜミスを犯すのか

下落相場が来ると人々は未来を悲観的に見る。株価が下がるとさらに下がりそうだし、ニュースが悪ければ状況がさらに悪化するように感じる。しかし市場は現在ではなく未来を反映する。最大の問題は、人々が未来を最も悲観的に見るタイミングが、しばしば最大の機会になるタイミングだということだ。2008年末、2020年3月——歴史的に最大の機会はほとんど恐怖の真只中にあった。しかしその瞬間には誰もそれを機会だとは思えない。

QLD投資家は金融危機をどのように見るべきか

QLDはナスダック100の約2倍の動きを追求する。したがって金融危機のような状況では下落幅もより大きく現れることがある。しかし本当のリスクはボラティリティではない。ボラティリティに対する自分の反応だ。もし投資家が下落に耐えられず底値で売却するならそれがリスクだ。逆に現金を準備しておいて計画された戦略を実行するなら暴落は機会にもなり得る。QLD -20%で分割買い付け開始、-30%で追加買い付け、-40%で積極的な買い付け、-50%で長期的な機会の検討——重要なのは感情ではなく計画だ。危機のときに必要なのは予測能力ではなく準備だ。

金融危機は人間の心理の歴史だ。人々は上昇相場でリスクを忘れ、下落相場で希望を忘れる。そして繰り返し同じミスを犯す。一方、成功した投資家たちは原則を守る。恐怖の中でも冷静さを保つ。時間が経つとその差は圧倒的な結果として現れる。

第8章 まとめ
金融危機は突然発生したのではなく、リスクを無視した結果だった。
上昇相場がむしろ最も危険な時期である場合がある。
私は安全マージンの重要性を強調する。
バフェットは恐怖の中に機会を見つけた。
暴落は投資家の心理を試す。
ETFがあっても危機はなくならない。
QLD投資家はボラティリティよりも自分の行動を管理すべきだ。
危機を生き残った人が結局複利の勝者になる。

覚えておくべき言葉

「危機は投資家を破滅させることもあるが、準備ができた投資家を富裕にすることもある。」''',
    // Ch9. コロナ暴落の教訓
    '''世界が止まったように見えた瞬間、市場は未来を見ていた
誰も予想しなかった危機

2020年初頭、ほとんどの投資家は平凡な一年になると思っていた。アメリカ経済は堅調で、失業率は低く、企業業績も良好だった。ナスダックは史上最高値に向かっていた。そのとき中国の武漢から始まった小さなニュースが世界を揺るがし始めた。最初は多くの人々が大したことではないと考えた。過去にも感染症は存在した。すぐ終わるだろうと考えた。

しかし状況は予想よりもはるかに速く悪化した。国々が国境を閉ざし始めた。都市が封鎖された。学校が閉まった。工場が止まり、飛行機が消え、人々は家の外に出られなくなった。現代経済の歴史上前例のない状況だった。

歴史上最も速い暴落

2020年2月末から市場は急激に揺れ始めた。そして3月、恐怖はパニックに変わった。S&P500はわずか数週間で30%以上下落した。ナスダックも急落した。QLDのようなレバレッジETFはより大きく揺れた。口座は毎日減り続け、ニュースはさらに暗くなった。人々は絶えず同じ質問をした。「今回は本当に違うのではないか？」「経済が完全に止まったのではないか？」「株をすべて売るべきか？」

以前の危機とコロナ危機が違った点は明確だった。金融危機は金融システムの問題だったし、ドットコムバブルはテクノロジー企業のバブル問題だった。しかしコロナは経済活動自体を止めてしまった。レストランが閉まり、航空会社が止まり、ホテルが空き、人々が消費できなくなった。経済のエンジンが消えたように見えた。

株式市場にはもともとボラティリティが存在する。しかしコロナ暴落は速度が速すぎた。ほとんどの投資家は暴落に適応する時間さえなかった。このような状況で人間の脳は本能的に反応する。「逃げなければならない。」恐怖は論理を圧倒する。多くの投資家が損失に耐えきれず市場を去った。

市場はなぜ反発したのか

コロナ暴落を理解するためには市場の本質を理解しなければならない。市場は現在を反映しない。市場は未来を反映する。2020年3月、投資家は二つの選択ができた。現在だけを見ること——病院は混雑し、経済は止まり、人々は不安だ。または未来を見ること——いつかはワクチンが開発されるだろうし、経済が再開されるだろうし、人々はまた消費するだろう。市場は結局二番目を選んだ。そして驚くべきことに市場は経済よりも先に回復し始めた。

バフェットはいつも同じ哲学を維持した。彼はアメリカ経済が長期的に成長すると信じた。彼は人類が問題を解決すると信じた。大恐慌も、世界大戦も、金融危機も克服した。コロナも結局克服した。バフェットが信じたのは短期的なニュースではなく、人間の適応能力だった。

コロナ後の世界はより強くなった

興味深いことに、コロナは一部の企業をむしろより強くした。リモートワークが広がり、クラウド産業が成長し、電子商取引が爆発的に拡大し、AI技術への投資も加速した。マイクロソフトとアマゾンはさらに成長し、エヌビディアはその後AI革命の中心に立つことになった。危機はいつも変化を生む。そして変化は新たな機会を生む。

コロナ暴落はETF投資家にとって非常に重要な教訓を残した。市場は予想以上に下落することがある。しかし同時に予想よりも速く回復することもある。ほとんどの投資家は回復のタイミングを合わせようとするが、歴史的にそれはほぼ不可能だった。最良の戦略はほとんどの場合シンプルだった。良い資産を保有して耐えること。そして必要であれば下落相場で追加買い付けをすること。

QLD投資家にコロナが教えてくれたこと

QLD投資家にとってコロナ暴落は特別な意味がある。レバレッジETFは恐怖をより大きく感じさせるからだ。ナスダックが下落するとQLDはより大きく揺れる。だから投資家は自分の原則を試される。本当に長期投資家なのか？本当に技術革新を信じているのか？本当に計画を守ることができるのか？コロナはこうした問いを投げかけた。そして市場は結局答えを示した。長期的な技術革新は止まらなかった。むしろ速くなった。

歴史を見ればすべての危機に共通点がある。その時期には永遠に終わらないように見える。しかし結局終わった。重要なのは危機を予測する能力ではない。危機の中でも原則を守る能力だ。長期投資家は未来を予言しない。代わりに、どんな未来が来ても生き残れるように準備する。

第9章 まとめ
コロナ暴落は現代の歴史上最も速い市場崩壊の一つだった。
市場は現在よりも未来を反映する。
優良企業の価値と市場価格は異なる場合がある。
バフェットは価格と価値を区別するよう強調する。
バフェットは人間の適応能力を信じた。
危機は新しい革新を加速させることもある。
ETF投資家は市場のタイミングよりも原則が重要だ。
QLD投資家はボラティリティの中でも長期的な技術革新を見据えるべきだ。

覚えておくべき言葉

「市場が最も暗く見える瞬間にも、未来は作られ続けている。」''',
    // Ch10. AI革命と現在の市場
    '''私たちはまた一つの歴史的な変曲点に立っているのか
人々はいつも未来を過小評価してきた

1903年、ライト兄弟が飛行機を作ったとき、多くの人は笑った。「人が空を飛ぶ？」それは非現実的な話のように聞こえた。1980年代にパーソナルコンピューターが登場したときも似ていた。ほとんどの人々はコンピューターが一部の専門家だけが使う機器になると考えた。1990年代のインターネットも同様だった。多くの人々はインターネットが単なる流行だと考えた。

しかし歴史は繰り返し同じ事実を示してきた。人間は短期的な変化は過大評価し、長期的な変化は過小評価する。そして今私たちはまた一つの巨大な変化の前に立っている。それが人工知能(AI)だ。

AIはなぜ特別なのか

過去の技術革新はほとんどが人間の肉体労働を助けるものだった。蒸気機関は重労働を代わりにし、自動車は移動を助け、コンピューターは計算を助け、インターネットは情報伝達を助けた。しかしAIは少し違う。AIは人間の知的労働を助ける。文章を書き、翻訳をし、分析をし、コードを書き、画像を作り、さらには意思決定を補助することもある。これは単なる技術発展ではない。生産性革命の始まりである可能性がある。

株式市場が長期的に上昇する理由は結局生産性にある。一人の人がより多くの価値を生み出せるようになれば企業利益が増加する。企業利益が増加すれば企業価値が増加する。そして結局株価が上昇する。産業革命、電気、コンピューター、インターネット——すべてが生産性を高めた。AIも同じ道を歩んでいる。したがって長期投資家は単にAI企業に投資するのではなく、生産性革命に投資しているのだ。

ドットコムバブルとAIは同じものか

多くの投資家が問う。「今のAIブームはドットコムバブルではないですか？」答えは単純ではない。AIは実際の革新だ。同様にインターネットも実際の革新だった。問題は技術と株価が常に同じ速度で動くわけではないということだ。ドットコムバブル当時、インターネットは本物だったが、一部の企業の価格は非現実的だった。今日のAIにも似たリスクが存在する可能性がある。良い技術が必ず良い投資収益を意味するわけではない。私が強調した理由もここにある。革新を信じることと、どんな価格でも投資することはまったく別の話だ。

エヌビディアが象徴するもの

2020年代のAI革命を語るとき最初に思い浮かぶ企業はエヌビディアだ。ほんの数年前まで、エヌビディアはゲームグラフィックカード会社というイメージが強かった。しかしAI時代が開けると状況は一変した。エヌビディアのGPUはAI産業の核心インフラになった。世界中の企業がAIモデルを開発するためにエヌビディアのチップを購入し始めた。重要なのは株価ではない。AIが実際の経済活動に影響を及ぼし始めたという事実だ。

バフェットはいつも新しい技術には慎重だった。彼は理解できる企業に集中し、流行を追いかけなかった。企業の競争力と収益創出能力を見た。だからいつも同じ問いを投げかけた。「この価格は合理的か？」「期待が過度に反映されているのではないか？」「安全マージンは存在するか？」これがバフェットの投資哲学の核心だ。

AI時代のETF投資とQLD

ほとんどの個人投資家はAI産業の最終的な勝者を当てることが難しい。10年後にどの企業が最も強いか正確に予測することはほぼ不可能だ。だからETFが重要だ。ETFは特定の企業ではなく産業全体の成長に参加させてくれる。ナスダック100にはAI革命の核心企業が多数含まれている。アップル、マイクロソフト、エヌビディア、アマゾン、メタ、ブロードコム——これらはすべてAI革命の恩恵を受ける可能性が高い。ETF投資家は個別の勝者を当てる負担なく革新の流れに参加できる。

QLD投資家にとってAIは非常に重要なテーマだ。QLDはナスダック100の約2倍の動きを追求するからだ。AI革命が成功するほどQLDは大きな恩恵を受ける可能性がある。しかし同時に期待が過熱するとボラティリティも大きくなる可能性がある。だから長期投資家は二つのことを同時に覚えておかなければならない。第一に、AIは実際の革新である可能性が高い。第二に、市場は短期的に過熱することがある。

多くの投資家はAIがどこまで発展するか予測しようとする。しかし歴史的に最も成功した投資家は未来を正確に予測した人々ではなかった。彼らは変化の方向を理解した人々だった。重要なのは明日の株価ではない。今後10年、20年の間に生産性がどのように変わるかを考えることだ。AIの真の価値は新しい製品ではない。生産性の向上だ。より少ない時間でより多くのことができるようにすることだ。人類の歴史を振り返ると生産性革命は常に経済成長を導いてきた。長期投資家はまさにここに投資する人だ。

第10章 まとめ
AIは単なる流行ではなく生産性革命である可能性が高い。
市場は長期的に生産性の向上を反映する。
ドットコムバブルの教訓は革新と価格を区別せよということだ。
エヌビディアはAI革命の代表的な事例だ。
私はいつも価格と安全マージンを強調する。
バフェットは流行よりも競争力を見る。
ETFはAI革命に参加する効率的な方法になり得る。
QLD投資家はAI革命の恩恵とボラティリティを同時に理解しなければならない。

