在我看来，市场只是一个工具。但大多数人把它当成主人。市场不是先知，它只是在报价，而这些价格并不总是正确的。

聪明的投资者善用市场

大多数人被市场所用。而我不同。当市场过热时我变得谨慎，当市场恐慌时我寻找机会。我不跟随市场情绪，我利用它。

第3章小结
市场每天报价，但报价并不总是准确的。
价格与价值是不同的事物。
