投資與投機是完全不同的遊戲

在我看來，投資必須滿足三個條件：第一，深入分析；第二，保護本金；第三，期望合理回報。不滿足這些條件的，從定義上說，都是投機。

重要的不是你買了什麼，而是你以何種心態買入。買入蘋果股票是投機，如果理由是「我認為明天會漲」。反之，在分析企業成長潛力後買入ETF，則更接近於投資。區分投資與投機的，不是產品，而是思維方式。

價格每天變動；價值緩慢變化

